/**
 * scientificArenaData.ts
 * -----------------------
 * SHS 3 Scientific Thinking Arena - 200 curriculum-aligned questions.
 * Used directly by the frontend arena without requiring backend connectivity.
 *
 * Covers 9 categories aligned to Ghana GES SHS 3 General Science:
 * Chemical Bonding & Reactions, Consumer Electronics & Digital Systems,
 * Energy & Environment, Forces, Pressure & Machines, Genetics & Heredity,
 * Human Body & Health, Industrial Chemistry & Biotechnology,
 * Science, Technology & Society, Waves, Light & Sound.
 */

import type { Question } from './challengesApi';

/** Obfuscation secret must match the backend */
const OB_SALT = 'ST_SEC_2024';

function hash(answerKey: string): string {
  if (typeof btoa === 'undefined') return '';
  return btoa(`${OB_SALT}:${answerKey}`);
}

// ── Raw Question Data ────────────────────────────────────────────
interface RawScientificQuestion {
  id: string;
  category: string;
  mission_title: string;
  question: string;
  options: [string, string, string, string];
  answer: string;
  explanation: string;
  xp: number;
}

const RAW: RawScientificQuestion[] = [
  { id: "ST3-SHS3-001", mission_title: "The Bond Builders", category: "Chemical Bonding & Reactions", question: "What type of bond is formed when electrons are transferred from a metal to a non-metal?", options: ["Covalent bond", "Ionic bond", "Metallic bond", "Hydrogen bond"], answer: "Ionic bond", explanation: "Ionic bonds form when a metal atom loses electrons to a non-metal atom. The metal becomes a positive ion and the non-metal becomes a negative ion; electrostatic attraction holds them together.", xp: 20 },
  { id: "ST3-SHS3-002", mission_title: "The Shared Electrons", category: "Chemical Bonding & Reactions", question: "In a covalent bond, what do the two atoms share?", options: ["Protons", "Neutrons", "Electrons", "Ions"], answer: "Protons", explanation: "Covalent bonds form when two atoms (usually non-metals) share one or more pairs of electrons. This sharing gives each atom a full outer shell, increasing stability.", xp: 20 },
  { id: "ST3-SHS3-003", mission_title: "The Alloy Architect", category: "Chemical Bonding & Reactions", question: "What is an alloy?", options: ["A pure metal element", "A mixture of a metal with one or more other elements to improve its properties", "A type of ionic compound", "A non-metal compound"], answer: "A mixture of a metal with one or more other elements to improve its properties", explanation: "An alloy is a mixture where a metal is combined with other elements (metals or non-metals) to enhance properties like strength, hardness, or corrosion resistance.", xp: 20 },
  { id: "ST3-SHS3-004", mission_title: "The Conservation Law", category: "Chemical Bonding & Reactions", question: "In a chemical reaction, what is CONSERVED according to the Law of Conservation of Mass?", options: ["The colour of the reactants", "The total mass - mass of reactants equals mass of products", "The temperature of the substances", "The volume of the substances"], answer: "The total mass - mass of reactants equals mass of products", explanation: "Lavoisier's Law of Conservation of Mass states that matter is neither created nor destroyed in a chemical reaction.", xp: 20 },
  { id: "ST3-SHS3-005", mission_title: "The Organic Carbon", category: "Chemical Bonding & Reactions", question: "What makes a compound 'organic' in chemistry?", options: ["It comes from a living organism only", "It contains carbon atoms (with some exceptions like CO2 and carbonates)", "It contains only hydrogen and oxygen", "It is always a gas at room temperature"], answer: "It contains carbon atoms (with some exceptions like CO2 and carbonates)", explanation: "Organic chemistry is the study of carbon-containing compounds. Carbon's ability to form four bonds and chain with other carbons makes it uniquely versatile.", xp: 20 },
  { id: "ST3-SHS3-006", mission_title: "The Hydrocarbons", category: "Chemical Bonding & Reactions", question: "What are hydrocarbons?", options: ["Compounds containing only hydrogen and nitrogen", "Compounds containing only carbon and hydrogen", "Compounds containing carbon, hydrogen, and oxygen", "Compounds containing hydrogen and oxygen only"], answer: "Compounds containing only carbon and hydrogen", explanation: "Hydrocarbons are the simplest organic compounds, made up of only carbon and hydrogen. They include alkanes (e.g., methane CH4), alkenes (e.g., ethene C2H4), and alkynes.", xp: 20 },
  { id: "ST3-SHS3-007", mission_title: "The Radioactivity Facts", category: "Chemical Bonding & Reactions", question: "What is radioactivity?", options: ["The ability of a material to reflect light", "The spontaneous emission of radiation from the unstable nucleus of an atom", "The absorption of heat by dense materials", "The process of forming ionic bonds"], answer: "The spontaneous emission of radiation from the unstable nucleus of an atom", explanation: "Radioactivity is the spontaneous decay of unstable atomic nuclei, releasing energy as radiation (alpha, beta, or gamma).", xp: 20 },
  { id: "ST3-SHS3-008", mission_title: "The Alpha Particle", category: "Chemical Bonding & Reactions", question: "An alpha (a) particle is identical to the nucleus of which element?", options: ["Hydrogen", "Helium", "Lithium", "Carbon"], answer: "Helium", explanation: "An alpha particle consists of 2 protons and 2 neutrons - identical to a helium-4 nucleus.", xp: 20 },
  { id: "ST3-SHS3-009", mission_title: "The Beta Particle", category: "Chemical Bonding & Reactions", question: "A beta (b) particle is a high-energy electron emitted from the nucleus. What nuclear change produces it?", options: ["A proton splits in two", "A neutron converts to a proton, emitting an electron", "A proton converts to a neutron", "Two electrons combine"], answer: "A neutron converts to a proton, emitting an electron", explanation: "In beta decay, a neutron in the nucleus converts to a proton, releasing a high-energy electron (beta particle) and an antineutrino.", xp: 20 },
  { id: "ST3-SHS3-010", mission_title: "The Gamma Ray", category: "Chemical Bonding & Reactions", question: "Gamma (g) radiation is different from alpha and beta radiation because it is:", options: ["A stream of particles with positive charge", "A stream of electrons", "Electromagnetic radiation (high-energy photons) with no charge or mass", "A stream of neutrons"], answer: "A stream of particles with positive charge", explanation: "Gamma rays are high-energy electromagnetic waves (photons). Unlike alpha and beta, they have no mass or charge.", xp: 20 },
  { id: "ST3-SHS3-011", mission_title: "The Half-Life", category: "Chemical Bonding & Reactions", question: "What is the HALF-LIFE of a radioactive isotope?", options: ["The time for all radioactive atoms to decay", "The time taken for half of the radioactive nuclei in a sample to decay", "The age of the radioactive material", "The time for the material to become completely safe"], answer: "The time taken for half of the radioactive nuclei in a sample to decay", explanation: "Half-life is the time for exactly half of the radioactive atoms in a sample to decay.", xp: 20 },
  { id: "ST3-SHS3-012", mission_title: "The Nuclear Fission", category: "Chemical Bonding & Reactions", question: "What is nuclear fission?", options: ["The joining of two light nuclei to form a heavier nucleus", "The splitting of a heavy atomic nucleus into two smaller nuclei, releasing enormous energy", "The emission of an alpha particle from an unstable nucleus", "The decay of a nucleus by emitting a beta particle"], answer: "The splitting of a heavy atomic nucleus into two smaller nuclei, releasing enormous energy", explanation: "Nuclear fission splits a heavy nucleus (like uranium-235) into smaller fragments when struck by a neutron.", xp: 20 },
  { id: "ST3-SHS3-013", mission_title: "The Nuclear Fusion", category: "Chemical Bonding & Reactions", question: "What is nuclear fusion?", options: ["The splitting of a heavy nucleus into two smaller ones", "The joining of two light nuclei to form a heavier nucleus, releasing even more energy than fission", "The emission of gamma radiation from a nucleus", "The process of removing electrons from an atom"], answer: "The joining of two light nuclei to form a heavier nucleus, releasing even more energy than fission", explanation: "Nuclear fusion joins two light nuclei (e.g., hydrogen isotopes) to form a heavier nucleus. This is the process that powers the Sun.", xp: 20 },
  { id: "ST3-SHS3-014", mission_title: "The Metallic Bond", category: "Chemical Bonding & Reactions", question: "What holds atoms together in a metallic bond?", options: ["Shared electron pairs between specific atoms", "Transfer of electrons from one atom to another", "A sea of delocalised (free-moving) electrons shared by all the positive metal ions", "Electrostatic attraction between opposite ions"], answer: "Shared electron pairs between specific atoms", explanation: "In metallic bonding, metal atoms release their outer electrons into a shared 'sea' of delocalised electrons.", xp: 20 },
  { id: "ST3-SHS3-015", mission_title: "The Steel Alloy", category: "Chemical Bonding & Reactions", question: "Steel is an alloy of iron and carbon. Why is steel STRONGER than pure iron?", options: ["Carbon ions replace iron ions, making a lighter structure", "Carbon atoms disrupt the regular layers of iron atoms, making it harder for layers to slide over each other", "Carbon increases the size of iron atoms", "Adding carbon removes impurities from iron"], answer: "Carbon atoms disrupt the regular layers of iron atoms, making it harder for layers to slide over each other", explanation: "In pure iron, layers of atoms can slide over each other easily (soft and ductile). Carbon atoms in steel are a different size, disrupting the regular pattern.", xp: 20 },
  { id: "ST3-SHS3-016", mission_title: "The Radiation Shield", category: "Chemical Bonding & Reactions", question: "Which material is MOST effective at shielding gamma radiation?", options: ["Paper", "Aluminium foil", "A few centimetres of water", "Thick lead or several metres of concrete"], answer: "Paper", explanation: "Alpha radiation is stopped by paper; beta by aluminium; gamma requires thick lead because it is highly penetrating electromagnetic radiation.", xp: 20 },
  { id: "ST3-SHS3-017", mission_title: "The Chain Reaction", category: "Chemical Bonding & Reactions", question: "In a nuclear power station, what is the purpose of the MODERATOR?", options: ["To speed up the neutrons from fission", "To absorb excess neutrons to control the reaction", "To slow down fast neutrons so they can trigger further fission in uranium-235", "To generate steam from the heat"], answer: "To speed up the neutrons from fission", explanation: "Fast neutrons from fission are too fast to cause further fission efficiently. The moderator slows them to thermal speeds.", xp: 20 },
  { id: "ST3-SHS3-018", mission_title: "The Applications of Radioactivity", category: "Chemical Bonding & Reactions", question: "Radioactive isotopes are used in medicine for treating cancer. Why is gamma radiation used in radiotherapy?", options: ["Gamma is stopped by skin so it cannot damage internal tissue", "Gamma radiation can penetrate the body and kill cancer cells", "Gamma radiation is harmless to all cells", "Gamma radiation only affects cancer cells, not healthy ones"], answer: "Gamma radiation can penetrate the body and kill cancer cells", explanation: "Gamma radiation penetrates deep into tissue, delivering energy to kill rapidly dividing cancer cells.", xp: 20 },
  { id: "ST3-SHS3-019", mission_title: "The Alkanes Family", category: "Chemical Bonding & Reactions", question: "Methane (CH4), ethane (C2H6), and propane (C3H8) belong to which organic compound family?", options: ["Alkenes", "Alkynes", "Alkanes", "Alcohols"], answer: "Alkenes", explanation: "Alkanes are saturated hydrocarbons with only single C-C bonds. The general formula is CnH2n+2.", xp: 20 },
  { id: "ST3-SHS3-020", mission_title: "The Double Bond", category: "Chemical Bonding & Reactions", question: "Alkenes differ from alkanes because alkenes contain:", options: ["Only single bonds between carbon atoms", "A carbon-carbon double bond (C=C)", "Triple bonds only", "No hydrogen atoms"], answer: "A carbon-carbon double bond (C=C)", explanation: "Alkenes are unsaturated hydrocarbons containing at least one C=C double bond.", xp: 20 },
  { id: "ST3-SHS3-021", mission_title: "The Combustion Reaction", category: "Chemical Bonding & Reactions", question: "Complete combustion of a hydrocarbon (e.g., methane) in excess oxygen produces:", options: ["Carbon monoxide and water only", "Carbon dioxide and water", "Carbon only", "Oxygen and nitrogen"], answer: "Carbon dioxide and water", explanation: "Complete combustion: hydrocarbon + excess oxygen -> carbon dioxide + water.", xp: 20 },
  { id: "ST3-SHS3-022", mission_title: "The Uses of Organic Chemistry", category: "Chemical Bonding & Reactions", question: "Plastics, medicines, fertilisers, and fuels are all products of organic chemistry. What key property of carbon makes this variety possible?", options: ["Carbon is the heaviest element", "Carbon can form four bonds and chain with other carbons to create millions of different molecular structures", "Carbon only bonds with hydrogen", "Carbon is the most abundant element on Earth"], answer: "Carbon can form four bonds and chain with other carbons to create millions of different molecular structures", explanation: "Carbon's tetravalency (ability to form 4 bonds) and its ability to form stable chains creates an almost unlimited number of organic molecules.", xp: 20 },
  { id: "ST3-SHS3-023", mission_title: "The DNA Discovery", category: "Genetics & Heredity", question: "What is DNA?", options: ["A type of protein that builds muscle", "Deoxyribonucleic Acid - the molecule that carries the genetic instructions for development, functioning, and reproduction of all living organisms", "A hormone that controls growth", "A type of fat found in cell membranes"], answer: "Deoxyribonucleic Acid - the molecule that carries the genetic instructions for development, functioning, and reproduction of all living organisms", explanation: "DNA is the hereditary material in all living organisms. It contains the genetic code that determines traits.", xp: 20 },
  { id: "ST3-SHS3-024", mission_title: "The Double Helix", category: "Genetics & Heredity", question: "What is the shape of the DNA molecule?", options: ["A single straight strand", "A double helix (two strands twisted around each other)", "A circular ring", "A triple helix"], answer: "A double helix (two strands twisted around each other)", explanation: "DNA has a double helix structure - two complementary strands wound around each other, like a twisted ladder.", xp: 20 },
  { id: "ST3-SHS3-025", mission_title: "The Gene Definition", category: "Genetics & Heredity", question: "What is a GENE?", options: ["A complete chromosome", "A segment of DNA that codes for a specific protein or trait", "The entire DNA of an organism", "A type of mutation"], answer: "A segment of DNA that codes for a specific protein or trait", explanation: "A gene is a specific sequence of DNA bases that codes for a particular protein. Genes are the basic units of heredity.", xp: 20 },
  { id: "ST3-SHS3-026", mission_title: "The Chromosome Count", category: "Genetics & Heredity", question: "How many chromosomes does a normal human body cell (somatic cell) contain?", options: ["23", "46", "48", "2"], answer: "46", explanation: "Human body cells contain 46 chromosomes arranged in 23 pairs.", xp: 20 },
  { id: "ST3-SHS3-027", mission_title: "The Gregor Mendel", category: "Genetics & Heredity", question: "Who is known as the 'Father of Genetics'?", options: ["Charles Darwin", "Louis Pasteur", "Gregor Mendel", "James Watson"], answer: "Charles Darwin", explanation: "Gregor Mendel, an Austrian monk, conducted pioneering pea plant breeding experiments and discovered the fundamental laws of heredity.", xp: 20 },
  { id: "ST3-SHS3-028", mission_title: "The Dominant Trait", category: "Genetics & Heredity", question: "What does it mean for an allele to be DOMINANT?", options: ["It is always passed on to offspring", "It is expressed in the phenotype even when only one copy is present (in a heterozygous individual)", "It causes disease", "It only appears in females"], answer: "It is expressed in the phenotype even when only one copy is present (in a heterozygous individual)", explanation: "A dominant allele masks the effect of a recessive allele. A heterozygous individual (Aa) shows the dominant phenotype.", xp: 20 },
  { id: "ST3-SHS3-029", mission_title: "The Recessive Trait", category: "Genetics & Heredity", question: "A recessive allele is only expressed in the phenotype when:", options: ["Only one copy is present", "Two copies are present (the individual is homozygous recessive)", "Combined with a dominant allele", "Found on the Y chromosome only"], answer: "Two copies are present (the individual is homozygous recessive)", explanation: "Recessive alleles only show in the phenotype when an individual has two copies of the recessive allele (aa).", xp: 20 },
  { id: "ST3-SHS3-030", mission_title: "The Punnett Square", category: "Genetics & Heredity", question: "Two heterozygous parents (Aa x Aa) cross. What is the probability of an offspring being homozygous recessive (aa)?", options: ["0%", "25%", "50%", "75%"], answer: "25%", explanation: "Punnett square for Aa x Aa gives: AA (25%), Aa (50%), aa (25%). Each offspring has a 25% chance of being homozygous recessive.", xp: 20 },
  { id: "ST3-SHS3-031", mission_title: "The Genotype vs Phenotype", category: "Genetics & Heredity", question: "What is the difference between genotype and phenotype?", options: ["They are the same thing", "Genotype is the genetic makeup (alleles); phenotype is the observable physical characteristics expressed", "Phenotype is the genetic makeup; genotype is the observable trait", "Genotype only refers to sex chromosomes"], answer: "Genotype is the genetic makeup (alleles); phenotype is the observable physical characteristics expressed", explanation: "Genotype = the genetic constitution (e.g., Aa). Phenotype = what you can observe (e.g., tall).", xp: 20 },
  { id: "ST3-SHS3-032", mission_title: "The Sex Determination", category: "Genetics & Heredity", question: "How is sex determined in humans?", options: ["By the temperature during development", "By the mother's genes only", "By the sex chromosomes: females have XX; males have XY", "By the father's blood type"], answer: "By the temperature during development", explanation: "Humans have 23 pairs of chromosomes. The 23rd pair are sex chromosomes - females have XX, males have XY.", xp: 20 },
  { id: "ST3-SHS3-033", mission_title: "The Mutation", category: "Genetics & Heredity", question: "What is a genetic MUTATION?", options: ["The normal process of DNA copying", "A change in the DNA sequence", "The transfer of genes from parent to offspring", "The expression of a recessive gene"], answer: "A change in the DNA sequence", explanation: "A mutation is a permanent change in the nucleotide sequence of DNA.", xp: 20 },
  { id: "ST3-SHS3-034", mission_title: "The Sickle Cell Disease", category: "Genetics & Heredity", question: "Sickle cell disease is caused by a mutation in which gene?", options: ["The insulin gene", "The haemoglobin gene", "The keratin gene", "The amylase gene"], answer: "The haemoglobin gene", explanation: "Sickle cell disease is caused by a point mutation in the haemoglobin gene (HbS).", xp: 20 },
  { id: "ST3-SHS3-035", mission_title: "The Sickle Cell Inheritance", category: "Genetics & Heredity", question: "In Ghana, sickle cell disease is common. A child with genotype HbSHbS has sickle cell disease. What are the genotypes of both parents?", options: ["Both parents must be HbSHbS", "Both parents must be HbAHbS (carriers)", "One parent is HbAHbA and one is HbSHbS", "Both parents must be HbAHbA"], answer: "Both parents must be HbAHbS (carriers)", explanation: "Sickle cell disease (HbSHbS) is autosomal recessive. Both parents must be carriers (HbAHbS).", xp: 20 },
  { id: "ST3-SHS3-036", mission_title: "The Meiosis Significance", category: "Genetics & Heredity", question: "Why is meiosis (the cell division that produces sex cells) important for genetic variation?", options: ["It produces identical daughter cells", "It doubles the chromosome number", "It creates genetic variation through crossing over and random assortment of chromosomes", "It repairs damaged DNA"], answer: "It produces identical daughter cells", explanation: "During meiosis, homologous chromosomes exchange segments (crossing over) and independently assort into daughter cells.", xp: 20 },
  { id: "ST3-SHS3-037", mission_title: "The Cloning", category: "Genetics & Heredity", question: "A clone has the same genetic material as its parent. How is this different from natural sexual reproduction?", options: ["Clones always look different from their parents", "Clones are produced sexually with two parents", "A clone is produced from a single parent without fertilisation - it is genetically identical to the parent", "Clones cannot reproduce"], answer: "Clones always look different from their parents", explanation: "Cloning produces genetically identical copies. In sexual reproduction, offspring have a unique combination of genes from two parents.", xp: 20 },
  { id: "ST3-SHS3-038", mission_title: "The Protein Synthesis", category: "Genetics & Heredity", question: "DNA carries the code for proteins. What is the correct sequence of events in protein synthesis?", options: ["Ribosomes -> DNA -> mRNA -> protein", "DNA -> mRNA (transcription in nucleus) -> ribosome -> protein (translation)", "mRNA -> DNA -> protein", "Protein -> DNA -> mRNA"], answer: "DNA -> mRNA (transcription in nucleus) -> ribosome -> protein (translation)", explanation: "DNA is transcribed into mRNA in the nucleus. The mRNA exits to a ribosome where it is translated into a sequence of amino acids.", xp: 20 },
  { id: "ST3-SHS3-039", mission_title: "The Blood Groups", category: "Genetics & Heredity", question: "Blood type is controlled by multiple alleles. A person with blood group O has genotype:", options: ["I^A I^B", "I^A I^A or I^A i", "I^B I^B or I^B i", "ii (two recessive alleles)"], answer: "I^A I^B", explanation: "The ABO blood group system has three alleles: I^A, I^B (codominant), and i (recessive). Blood group O requires genotype ii.", xp: 20 },
  { id: "ST3-SHS3-040", mission_title: "The Genetic Counselling", category: "Genetics & Heredity", question: "Why is genetic counselling important in Ghana, particularly regarding sickle cell disease?", options: ["It tells parents the sex of their child", "It helps couples understand their genetic risk of passing inherited conditions to offspring and make informed reproductive decisions", "It is required by law before marriage", "It can cure genetic diseases"], answer: "It helps couples understand their genetic risk of passing inherited conditions to offspring and make informed reproductive decisions", explanation: "Genetic counselling helps people understand their genetic makeup and risk of passing conditions like sickle cell disease to children.", xp: 20 },
  { id: "ST3-SHS3-041", mission_title: "The Evolution Connection", category: "Genetics & Heredity", question: "How do mutations contribute to evolution?", options: ["Mutations always decrease an organism's fitness", "Mutations can introduce new alleles into a population; if beneficial, they may be selected for over generations - driving evolution", "Mutations only cause disease", "Mutations are immediately eliminated"], answer: "Mutations can introduce new alleles into a population; if beneficial, they may be selected for over generations - driving evolution", explanation: "Mutations are the ultimate source of new genetic variation. Natural selection acts on this variation to drive evolution.", xp: 20 },
  { id: "ST3-SHS3-042", mission_title: "The Biotechnology Application", category: "Genetics & Heredity", question: "Genetic engineering in agriculture has been used in Ghana to develop improved crop varieties. What does this involve?", options: ["Traditional cross-breeding over many generations", "Directly altering an organism's DNA to introduce specific traits", "Exposing crops to radiation to cause random mutations", "Selective harvesting of the best plants"], answer: "Directly altering an organism's DNA to introduce specific traits", explanation: "Genetic engineering directly inserts, deletes, or modifies specific genes in an organism's DNA.", xp: 20 },
  { id: "ST3-SHS3-043", mission_title: "The Natural Selection", category: "Genetics & Heredity", question: "In Ghana, the sickle cell trait (HbAS) is common in regions where malaria is endemic. This is because:", options: ["The HbS allele provides no benefit", "HbAS individuals have some protection against severe malaria, so the allele persists in the population despite causing disease in HbSS individuals", "Malaria cures sickle cell disease", "HbAS individuals are immune to all diseases"], answer: "HbAS individuals have some protection against severe malaria, so the allele persists in the population despite causing disease in HbSS individuals", explanation: "This is a classic example of heterozygote advantage. HbAS (sickle cell trait) individuals are less susceptible to severe malaria. The HbS allele persists at high frequency in malaria-endemic regions because the benefits in heterozygotes outweigh the costs in homozygotes.", xp: 30 },
  { id: "ST3-SHS3-045", mission_title: "The Wave Fundamentals", category: "Waves, Light & Sound", question: "What is a WAVE?", options: ["The movement of water in the ocean only", "A disturbance that transfers energy from one place to another without transferring matter", "The movement of electrons in a wire", "A type of chemical bond"], answer: "A disturbance that transfers energy from one place to another without transferring matter", explanation: "A wave is a propagating disturbance that transfers energy without permanently displacing the medium.", xp: 20 },
  { id: "ST3-SHS3-046", mission_title: "The Transverse Wave", category: "Waves, Light & Sound", question: "In a transverse wave, the oscillation (vibration) is:", options: ["In the same direction as the wave travels", "At right angles (perpendicular) to the direction the wave travels", "At 45 degrees to the wave direction", "In a circular motion"], answer: "At right angles (perpendicular) to the direction the wave travels", explanation: "In transverse waves, particles vibrate perpendicular to the direction of wave travel. Light and electromagnetic waves are transverse.", xp: 20 },
  { id: "ST3-SHS3-047", mission_title: "The Longitudinal Wave", category: "Waves, Light & Sound", question: "Sound is a longitudinal wave. What does this mean about how its particles vibrate?", options: ["Particles vibrate at right angles to the wave direction", "Particles vibrate parallel to the wave travels, creating compressions and rarefactions", "Particles move in circles", "Particles do not vibrate at all"], answer: "Particles vibrate parallel to the wave travels, creating compressions and rarefactions", explanation: "In longitudinal waves, particles vibrate back and forth along the same axis as wave travel, creating compressions and rarefactions.", xp: 20 },
  { id: "ST3-SHS3-048", mission_title: "The Wave Properties", category: "Waves, Light & Sound", question: "What is the FREQUENCY of a wave?", options: ["The maximum displacement of particles from their rest position", "The distance between two successive crests", "The number of complete wave cycles passing a point per second, measured in Hertz (Hz)", "The speed at which the wave travels"], answer: "The maximum displacement of particles from their rest position", explanation: "Frequency (f) is the number of complete oscillations per second. 1 Hz = 1 cycle per second.", xp: 20 },
  { id: "ST3-SHS3-049", mission_title: "The Wave Equation", category: "Waves, Light & Sound", question: "The wave equation is v = fL. If a wave has frequency 500 Hz and wavelength 0.4 m, what is its speed?", options: ["125 m/s", "200 m/s", "500 m/s", "1250 m/s"], answer: "200 m/s", explanation: "v = f x wavelength = 500 Hz x 0.4 m = 200 m/s.", xp: 20 },
  { id: "ST3-SHS3-050", mission_title: "The Amplitude", category: "Waves, Light & Sound", question: "What is the AMPLITUDE of a wave?", options: ["The distance between two crests", "The number of waves per second", "The maximum displacement of a particle from its undisturbed (rest) position", "The speed of the wave"], answer: "The distance between two crests", explanation: "Amplitude is the maximum displacement from the equilibrium position to the peak or trough of a wave.", xp: 20 },
  { id: "ST3-SHS3-051", mission_title: "The Electromagnetic Spectrum", category: "Waves, Light & Sound", question: "Which of the following correctly orders electromagnetic waves from LONGEST to SHORTEST wavelength?", options: ["Gamma -> X-ray -> UV -> visible -> infrared -> microwave -> radio", "Radio -> microwave -> infrared -> visible light -> UV -> X-ray -> gamma", "Visible -> UV -> infrared -> radio -> gamma", "X-ray -> UV -> visible -> gamma -> microwave -> radio"], answer: "Radio -> microwave -> infrared -> visible light -> UV -> X-ray -> gamma", explanation: "The EM spectrum from longest to shortest wavelength: Radio, Microwave, Infrared, Visible, Ultraviolet, X-ray, Gamma ray.", xp: 20 },
  { id: "ST3-SHS3-052", mission_title: "The Speed of Light", category: "Waves, Light & Sound", question: "What is the speed of electromagnetic waves (including light) in a vacuum?", options: ["340 m/s", "3 x 10^6 m/s", "3 x 10^8 m/s", "3 x 10^10 m/s"], answer: "340 m/s", explanation: "The speed of light in a vacuum is approximately 3 x 10^8 m/s (300,000 km/s).", xp: 20 },
  { id: "ST3-SHS3-053", mission_title: "The Reflection Law", category: "Waves, Light & Sound", question: "The law of reflection states that:", options: ["The angle of incidence equals the angle of refraction", "The angle of incidence equals the angle of reflection (both measured from the normal)", "Light always reflects at 90 degrees", "The angle of reflection is always greater than the angle of incidence"], answer: "The angle of incidence equals the angle of reflection (both measured from the normal)", explanation: "Law of reflection: angle of incidence = angle of reflection. Both measured from the normal.", xp: 20 },
  { id: "ST3-SHS3-054", mission_title: "The Refraction", category: "Waves, Light & Sound", question: "When light passes from air into glass, it slows down and bends toward the normal. This is called:", options: ["Reflection", "Diffraction", "Refraction", "Interference"], answer: "Reflection", explanation: "Refraction is the bending of a wave when it changes speed by passing into a different medium.", xp: 20 },
  { id: "ST3-SHS3-055", mission_title: "The Sound Speed", category: "Waves, Light & Sound", question: "Sound travels at approximately 340 m/s in air. In which medium does sound travel FASTEST?", options: ["Air", "Water", "Steel/solids", "A vacuum"], answer: "Air", explanation: "Sound travels faster in denser, more elastic media: solid > liquid > gas. In steel, sound travels at ~5,100 m/s.", xp: 20 },
  { id: "ST3-SHS3-056", mission_title: "The Hearing Range", category: "Waves, Light & Sound", question: "The human ear can detect sound in the frequency range approximately:", options: ["2 Hz to 200 Hz", "20 Hz to 20,000 Hz (20 kHz)", "200 Hz to 2,000,000 Hz", "1 Hz to 1,000 Hz"], answer: "20 Hz to 20,000 Hz (20 kHz)", explanation: "Humans can hear sounds from about 20 Hz to 20,000 Hz.", xp: 20 },
  { id: "ST3-SHS3-057", mission_title: "The Ultrasound", category: "Waves, Light & Sound", question: "Ultrasound is used in medical scanning. Why is it safe for scanning unborn babies?", options: ["Ultrasound uses X-rays which are safe in small doses", "Ultrasound uses high-frequency sound waves which reflect off tissues - no ionising radiation is involved", "Ultrasound uses visible light to see inside the body", "Ultrasound uses gamma rays at very low doses"], answer: "Ultrasound uses high-frequency sound waves which reflect off tissues - no ionising radiation is involved", explanation: "Ultrasound scanning uses high-frequency sound waves that bounce off internal structures - no ionising radiation.", xp: 20 },
  { id: "ST3-SHS3-058", mission_title: "The Total Internal Reflection", category: "Waves, Light & Sound", question: "Optical fibres transmit light signals using total internal reflection. What condition must be met for this to occur?", options: ["Light must travel from a less dense to a more dense medium", "Light must hit the boundary at an angle less than the critical angle", "Light must travel from a denser medium and hit the boundary at an angle greater than the critical angle", "Light must travel in a vacuum"], answer: "Light must travel from a less dense to a more dense medium", explanation: "Total internal reflection is used in fibre optic cables for high-speed internet and medical endoscopes.", xp: 20 },
  { id: "ST3-SHS3-059", mission_title: "The Diffraction", category: "Waves, Light & Sound", question: "Diffraction is the spreading of waves around obstacles or through gaps. When is diffraction most noticeable?", options: ["When the gap is much larger than the wavelength", "When the gap size is similar to or smaller than the wavelength", "When the wave travels in a vacuum", "When the wave frequency is very high"], answer: "When the gap size is similar to or smaller than the wavelength", explanation: "Diffraction is most pronounced when the gap or obstacle is similar in size to the wavelength.", xp: 20 },
  { id: "ST3-SHS3-060", mission_title: "The Seismic Waves", category: "Waves, Light & Sound", question: "Earthquakes produce seismic waves. P-waves (primary waves) are:", options: ["Transverse waves that travel through solids only", "Longitudinal waves that travel through solids, liquids, and gases", "Surface waves only", "Electromagnetic waves produced by earthquakes"], answer: "Longitudinal waves that travel through solids, liquids, and gases", explanation: "P-waves are longitudinal seismic waves that travel through solids, liquids, and gases.", xp: 20 },
  { id: "ST3-SHS3-061", mission_title: "The Doppler Effect", category: "Waves, Light & Sound", question: "A police car races toward you with its siren on. You hear the siren at a higher pitch than when it passes. This is:", options: ["The refraction effect", "The Doppler effect - the perceived frequency changes due to relative motion", "The amplitude effect", "The diffraction effect"], answer: "The Doppler effect - the perceived frequency changes due to relative motion", explanation: "When a wave source moves toward you, waves are compressed (higher pitch). When it moves away, they stretch.", xp: 20 },
  { id: "ST3-SHS3-062", mission_title: "The Colour Spectrum", category: "Waves, Light & Sound", question: "When white light passes through a prism, it splits into colours. This occurs because:", options: ["Different colours have different amplitudes", "Different colours (frequencies) travel at slightly different speeds in glass, causing different amounts of refraction", "The prism absorbs some colours", "All colours have the same wavelength"], answer: "Different colours (frequencies) travel at slightly different speeds in glass, causing different amounts of refraction", explanation: "Dispersion occurs because different frequencies of light are refracted by different amounts in glass.", xp: 20 },
  { id: "ST3-SHS3-063", mission_title: "The Wavelength and Colour", category: "Waves, Light & Sound", question: "Which colour of visible light has the LONGEST wavelength?", options: ["Violet", "Blue", "Green", "Red"], answer: "Violet", explanation: "Red has the longest wavelength (~700 nm). Violet has the shortest (~400 nm).", xp: 20 },
  { id: "ST3-SHS3-064", mission_title: "The Noise Pollution", category: "Waves, Light & Sound", question: "Noise pollution is a growing concern in Ghanaian cities. Which unit measures the loudness of sound?", options: ["Hertz (Hz)", "Metres per second (m/s)", "Decibels (dB)", "Newtons (N)"], answer: "Hertz (Hz)", explanation: "Sound intensity is measured in decibels (dB). Prolonged exposure above 85 dB can cause hearing damage.", xp: 20 },
  { id: "ST3-SHS3-065", mission_title: "The Infrared Applications", category: "Waves, Light & Sound", question: "Which of the following is a practical application of INFRARED radiation?", options: ["Sterilising medical equipment", "Treating cancer cells", "Thermal imaging cameras and remote controls", "GPS navigation"], answer: "Sterilising medical equipment", explanation: "Infrared radiation is used in thermal/night-vision cameras and TV/device remote controls.", xp: 20 },
  { id: "ST3-SHS3-066", mission_title: "The X-Ray Uses", category: "Waves, Light & Sound", question: "X-rays are used in hospitals to image bones. Why are X-rays useful for this?", options: ["X-rays reflect off soft tissue only", "X-rays penetrate soft tissue but are absorbed by denser material like bone, creating an image", "X-rays only travel in a vacuum", "X-rays are the same as gamma rays"], answer: "X-rays penetrate soft tissue but are absorbed by denser material like bone, creating an image", explanation: "X-rays pass through soft tissue but are absorbed by bones, creating shadow images.", xp: 20 },
  { id: "ST3-SHS3-067", mission_title: "The Pressure Principle", category: "Forces, Pressure & Machines", question: "What is the formula for PRESSURE?", options: ["Pressure = Force x Area", "Pressure = Mass x Velocity", "Pressure = Force / Area", "Pressure = Weight / Volume"], answer: "Pressure = Force x Area", explanation: "Pressure = Force / Area (P = F/A). Unit: Pascal (Pa) = N/m2.", xp: 20 },
  { id: "ST3-SHS3-068", mission_title: "The Pressure Calculation", category: "Forces, Pressure & Machines", question: "A force of 100 N acts on an area of 0.5 m2. What is the pressure?", options: ["50 Pa", "100 Pa", "200 Pa", "500 Pa"], answer: "50 Pa", explanation: "P = F/A = 100 N / 0.5 m2 = 200 Pa.", xp: 20 },
  { id: "ST3-SHS3-069", mission_title: "The Atmospheric Pressure", category: "Forces, Pressure & Machines", question: "Standard atmospheric pressure at sea level is approximately:", options: ["100 Pa", "1,000 Pa", "101,325 Pa (approx 100,000 Pa or 1 atm)", "1,000,000 Pa"], answer: "100 Pa", explanation: "Standard atmospheric pressure is ~101,325 Pa.", xp: 20 },
  { id: "ST3-SHS3-070", mission_title: "The Hydraulic System", category: "Forces, Pressure & Machines", question: "Hydraulic machines use Pascal's Principle. What does this state?", options: ["Pressure applied to a confined fluid is transmitted equally in all directions throughout the fluid", "Fluids always flow from high to low pressure", "Pressure in a fluid increases with depth", "Liquids cannot be compressed"], answer: "Pressure applied to a confined fluid is transmitted equally in all directions throughout the fluid", explanation: "Pascal's Principle: pressure applied to an enclosed fluid is transmitted undiminished in all directions.", xp: 20 },
  { id: "ST3-SHS3-071", mission_title: "The Moment of a Force", category: "Forces, Pressure & Machines", question: "What is the MOMENT of a force?", options: ["The mass of the object", "The turning effect of a force about a pivot = Force x perpendicular distance", "The speed at which a force is applied", "The direction of a force"], answer: "The turning effect of a force about a pivot = Force x perpendicular distance", explanation: "Moment = Force x perpendicular distance from pivot. Unit: Newton-metres (N-m).", xp: 20 },
  { id: "ST3-SHS3-072", mission_title: "The Principle of Moments", category: "Forces, Pressure & Machines", question: "For a body in rotational equilibrium, the Principle of Moments states:", options: ["All forces must be equal", "Total clockwise moment about any pivot = total anticlockwise moment", "There must be no forces acting", "The net force must be upward"], answer: "Total clockwise moment about any pivot = total anticlockwise moment", explanation: "The Principle of Moments: sum of clockwise moments = sum of anticlockwise moments about any pivot.", xp: 20 },
  { id: "ST3-SHS3-073", mission_title: "The Lever Classes", category: "Forces, Pressure & Machines", question: "A wheelbarrow is a Class 2 lever (load between effort and pivot). What mechanical advantage does this give?", options: ["Less than 1", "Greater than 1 - a smaller effort can move a larger load", "Exactly 1", "The lever cannot move any load"], answer: "Greater than 1 - a smaller effort can move a larger load", explanation: "A Class 2 lever always has MA > 1, so output force exceeds input force.", xp: 20 },
  { id: "ST3-SHS3-074", mission_title: "The Mechanical Advantage", category: "Forces, Pressure & Machines", question: "What is MECHANICAL ADVANTAGE?", options: ["The speed gained by using a machine", "The ratio of load to effort: MA = Load / Effort", "The energy wasted in a machine", "The distance the effort moves"], answer: "The ratio of load to effort: MA = Load / Effort", explanation: "MA > 1 means a small effort moves a large load.", xp: 20 },
  { id: "ST3-SHS3-075", mission_title: "The Inclined Plane", category: "Forces, Pressure & Machines", question: "A ramp (inclined plane) is a simple machine. How does it make it easier to move a heavy load?", options: ["It increases the force required", "It decreases the distance", "It spreads the work over a longer distance, requiring less force", "It uses compressed air"], answer: "It increases the force required", explanation: "A ramp allows the same work to be done with less force over a greater distance.", xp: 20 },
  { id: "ST3-SHS3-076", mission_title: "The Efficiency", category: "Forces, Pressure & Machines", question: "A machine does 500 J of useful work but uses 800 J of energy input. What is its efficiency?", options: ["37.5%", "50%", "62.5%", "160%"], answer: "37.5%", explanation: "Efficiency = (useful output / total input) x 100% = (500/800) x 100% = 62.5%.", xp: 20 },
  { id: "ST3-SHS3-077", mission_title: "The Circular Motion", category: "Forces, Pressure & Machines", question: "An object moving in a circle at constant speed is ACCELERATING. Why?", options: ["Its speed is increasing", "Its direction is constantly changing - a change in direction means acceleration", "It is slowing down due to gravity", "It is not accelerating if speed is constant"], answer: "Its direction is constantly changing - a change in direction means acceleration", explanation: "Acceleration is any change in velocity. Velocity is a vector with both magnitude AND direction.", xp: 20 },
  { id: "ST3-SHS3-078", mission_title: "The Centripetal Force", category: "Forces, Pressure & Machines", question: "What provides the centripetal force for a satellite orbiting Earth?", options: ["The rocket engines", "Gravity - Earth's gravitational attraction", "Air resistance", "The momentum of the satellite"], answer: "Gravity - Earth's gravitational attraction", explanation: "For a satellite, gravity provides the centripetal force toward the centre of the orbit.", xp: 20 },
  { id: "ST3-SHS3-079", mission_title: "The Pressure in Fluids", category: "Forces, Pressure & Machines", question: "Pressure in a fluid increases with depth. Which equation correctly shows this?", options: ["P = rho / gh", "P = rho x g x h (density x g x height of fluid above)", "P = g / rho x h", "P = rho x g / h"], answer: "P = rho x g x h (density x g x height of fluid above)", explanation: "P = rho x g x h where rho = density, g = gravitational field strength, h = depth.", xp: 20 },
  { id: "ST3-SHS3-080", mission_title: "The Simple Pulley", category: "Forces, Pressure & Machines", question: "A single fixed pulley (like a flagpole pulley) has MA = 1. What advantage does it offer?", options: ["It multiplies force", "It changes the direction of the effort force - pull down to lift up", "It reduces distance", "It reduces friction"], answer: "It changes the direction of the effort force - pull down to lift up", explanation: "A single fixed pulley does not multiply force but changes the direction of effort.", xp: 20 },
  { id: "ST3-SHS3-082", mission_title: "The Blood Pressure", category: "Forces, Pressure & Machines", question: "Blood pressure is HIGHER in the lower limbs than at the head. Why?", options: ["The heart pumps faster to the legs", "Blood in the lower limbs has more pressure due to the greater depth/height of fluid (blood) above them", "Blood in legs is denser", "Arteries in the legs are narrower"], answer: "Blood in the lower limbs has more pressure due to the greater depth/height of fluid (blood) above them", explanation: "Using P = rho x g x h, pressure in a fluid column increases with depth.", xp: 20 },
  { id: "ST3-SHS3-084", mission_title: "The Three Classes of Levers", category: "Forces, Pressure & Machines", question: "Which class of lever has the EFFORT between the pivot and the load?", options: ["Class 1 lever", "Class 2 lever", "Class 3 lever", "Class 4 lever"], answer: "Class 1 lever", explanation: "Class 3 levers have effort between pivot and load. The human forearm is a Class 3 lever.", xp: 20 },
  { id: "ST3-SHS3-085", mission_title: "The Atmospheric Applications", category: "Forces, Pressure & Machines", question: "A syringe draws liquid by pulling back the plunger. What force causes the liquid to enter?", options: ["Suction from the plunger", "Atmospheric pressure outside pushes the liquid in when the pressure inside is reduced", "Gravity pulling the liquid upward", "Osmosis driving water in"], answer: "Atmospheric pressure outside pushes the liquid in when the pressure inside is reduced", explanation: "Pulling the plunger back reduces pressure inside the syringe below atmospheric pressure.", xp: 20 },
  { id: "ST3-SHS3-087", mission_title: "The Torque Challenge", category: "Forces, Pressure & Machines", question: "A spanner of length 0.3 m is used with a force of 40 N applied perpendicular. What is the moment?", options: ["0.0075 N-m", "7.5 N-m", "12 N-m", "133 N-m"], answer: "0.0075 N-m", explanation: "Moment = Force x perpendicular distance = 40 N x 0.3 m = 12 N-m.", xp: 20 },
  { id: "ST3-SHS3-088", mission_title: "The Floating and Sinking", category: "Forces, Pressure & Machines", question: "Archimedes' Principle states that an object immersed in a fluid experiences an upthrust equal to:", options: ["Its weight in air", "The weight of fluid displaced by the object", "The density of the fluid only", "The volume of the object only"], answer: "The weight of fluid displaced by the object", explanation: "Upthrust = weight of fluid displaced. Ships float by displacing a large volume of water.", xp: 20 },
  { id: "ST3-SHS3-089", mission_title: "The Digital World", category: "Consumer Electronics & Digital Systems", question: "What is the difference between ANALOGUE and DIGITAL signals?", options: ["Analogue signals are digital", "Analogue signals vary continuously; digital signals use discrete values (0s and 1s)", "Digital signals are louder", "There is no practical difference"], answer: "Analogue signals vary continuously; digital signals use discrete values (0s and 1s)", explanation: "Analogue signals can take any value within a range. Digital signals use only 0 and 1.", xp: 20 },
  { id: "ST3-SHS3-090", mission_title: "The Binary System", category: "Consumer Electronics & Digital Systems", question: "What does the binary number '1010' represent in decimal?", options: ["2", "5", "10", "12"], answer: "2", explanation: "Binary 1010 = (1x8) + (0x4) + (1x2) + (0x1) = 10 in decimal.", xp: 20 },
  { id: "ST3-SHS3-091", mission_title: "The Logic Gates", category: "Consumer Electronics & Digital Systems", question: "What is the output of an AND gate when both inputs are 1?", options: ["0 (LOW)", "1 (HIGH)", "Depends on the voltage", "It produces a pulse"], answer: "1 (HIGH)", explanation: "AND gate outputs 1 only when ALL inputs are 1.", xp: 20 },
  { id: "ST3-SHS3-092", mission_title: "The OR Gate", category: "Consumer Electronics & Digital Systems", question: "What is the output of an OR gate when one input is 1 and the other is 0?", options: ["0 (LOW)", "1 (HIGH)", "Cannot be determined", "Depends on which input is 1"], answer: "1 (HIGH)", explanation: "OR gate outputs 1 when ANY input is 1.", xp: 20 },
  { id: "ST3-SHS3-093", mission_title: "The NOT Gate", category: "Consumer Electronics & Digital Systems", question: "A NOT gate (inverter) has an input of 0. What is the output?", options: ["0", "1 (inverts/flips the input)", "Depends on voltage", "No output"], answer: "1 (inverts/flips the input)", explanation: "A NOT gate inverts its input: if input = 0, output = 1.", xp: 20 },
  { id: "ST3-SHS3-094", mission_title: "The NAND Gate", category: "Consumer Electronics & Digital Systems", question: "A NAND gate is AND followed by NOT. Output when BOTH inputs are 1?", options: ["1 (HIGH)", "0 (LOW)", "Depends on power supply", "NAND only works with one input"], answer: "0 (LOW)", explanation: "NAND = NOT AND. When both inputs are 1, AND gives 1, NOT(1) = 0.", xp: 20 },
  { id: "ST3-SHS3-095", mission_title: "The Microcontroller", category: "Consumer Electronics & Digital Systems", question: "What is a MICROCONTROLLER?", options: ["A large computer in a factory", "A small integrated circuit containing a processor, memory, and programmable I/O", "A type of capacitor", "A temperature sensor"], answer: "A small integrated circuit containing a processor, memory, and programmable I/O", explanation: "A microcontroller contains CPU, memory and I/O peripherals on one chip.", xp: 20 },
  { id: "ST3-SHS3-096", mission_title: "The Communication Technology", category: "Consumer Electronics & Digital Systems", question: "Which technology uses electromagnetic waves to transmit data wirelessly?", options: ["Copper wire cables", "Optical fibre", "Radio frequency (RF) waves - including WiFi, Bluetooth, and mobile networks", "Hydraulic pressure waves"], answer: "Copper wire cables", explanation: "Wireless technologies use radio frequency electromagnetic waves to transmit digital data.", xp: 20 },
  { id: "ST3-SHS3-097", mission_title: "The GPS Technology", category: "Consumer Electronics & Digital Systems", question: "GPS uses signals from satellites to determine location. What type of waves carry these signals?", options: ["Sound waves", "Radio waves (microwave frequency range)", "Light waves", "Infrared waves"], answer: "Radio waves (microwave frequency range)", explanation: "GPS satellites transmit microwave radio signals. Receivers calculate position by measuring time delays.", xp: 20 },
  { id: "ST3-SHS3-098", mission_title: "The Sensor Systems", category: "Consumer Electronics & Digital Systems", question: "A temperature sensor converts temperature into an electrical signal. What type of device is this?", options: ["An actuator", "A transistor switch", "A transducer (sensor)", "A logic gate"], answer: "An actuator", explanation: "A transducer converts one form of energy to another. Sensors are input transducers.", xp: 20 },
  { id: "ST3-SHS3-099", mission_title: "The Feedback System", category: "Consumer Electronics & Digital Systems", question: "A thermostat uses a FEEDBACK system. What does feedback do in a control system?", options: ["It adds more energy", "It compares output to desired value and adjusts input to correct differences", "It removes all input", "It increases power consumption"], answer: "It compares output to desired value and adjusts input to correct differences", explanation: "Negative feedback compares actual output to the desired setpoint and reduces any difference.", xp: 20 },
  { id: "ST3-SHS3-100", mission_title: "The Internet of Things", category: "Consumer Electronics & Digital Systems", question: "The Internet of Things (IoT) refers to:", options: ["The physical infrastructure of cables and servers", "A network of everyday physical devices with sensors that connect and exchange data over the internet", "The World Wide Web", "Social media platforms"], answer: "A network of everyday physical devices with sensors that connect and exchange data over the internet", explanation: "IoT describes smart devices connected to the internet that collect and share data.", xp: 20 },
  { id: "ST3-SHS3-101", mission_title: "The Immune System", category: "Human Body & Health", question: "What is the role of the IMMUNE SYSTEM?", options: ["Digest food and absorb nutrients", "Protect the body from disease-causing organisms (pathogens) and foreign substances", "Transport oxygen in the blood", "Regulate body temperature only"], answer: "Protect the body from disease-causing organisms (pathogens) and foreign substances", explanation: "The immune system defends the body against pathogens including bacteria, viruses, fungi, and parasites.", xp: 20 },
  { id: "ST3-SHS3-102", mission_title: "The Antibodies", category: "Human Body & Health", question: "What are ANTIBODIES?", options: ["White blood cells that engulf pathogens", "Proteins produced by B-lymphocytes that bind specifically to a pathogen's antigens and neutralise it", "Hormones from the endocrine system", "Chemical messengers from the nervous system"], answer: "Proteins produced by B-lymphocytes that bind specifically to a pathogen's antigens and neutralise it", explanation: "Antibodies are Y-shaped proteins that bind specifically to unique antigens on pathogens.", xp: 20 },
  { id: "ST3-SHS3-103", mission_title: "The Vaccination", category: "Human Body & Health", question: "How does vaccination protect against infectious disease?", options: ["Vaccines contain antibiotics that kill pathogens", "Vaccines introduce a weakened form of the pathogen, stimulating the immune system without causing disease", "Vaccines directly kill viruses", "Vaccines strengthen muscles"], answer: "Vaccines introduce a weakened form of the pathogen, stimulating the immune system without causing disease", explanation: "Vaccination triggers immune response and production of memory cells without causing the full disease.", xp: 20 },
  { id: "ST3-SHS3-105", mission_title: "The Herd Immunity", category: "Human Body & Health", question: "What is HERD IMMUNITY?", options: ["Immunity only for farm animals", "When a high proportion of a population is immune, protecting unvaccinated individuals", "A type of vaccine for the whole community", "The natural immunity of all animals"], answer: "When a high proportion of a population is immune, protecting unvaccinated individuals", explanation: "Herd immunity breaks transmission chains, protecting even those who cannot be vaccinated.", xp: 20 },
  { id: "ST3-SHS3-107", mission_title: "The Nervous System", category: "Human Body & Health", question: "The CENTRAL NERVOUS SYSTEM (CNS) consists of:", options: ["The brain, spinal cord, and all peripheral nerves", "The brain and spinal cord only", "All nerves in the body", "The sympathetic and parasympathetic systems only"], answer: "The brain and spinal cord only", explanation: "The CNS consists of the brain (control centre) and spinal cord (relay).", xp: 20 },
  { id: "ST3-SHS3-108", mission_title: "The Reflex Arc", category: "Human Body & Health", question: "When you accidentally touch a hot surface, your hand pulls away BEFORE you feel pain. Where is the reflex arc processed?", options: ["The brain cortex", "The spinal cord - bypassing the brain for faster response", "The cerebellum", "The thalamus"], answer: "The spinal cord - bypassing the brain for faster response", explanation: "Simple reflex arcs are processed in the spinal cord for a very fast response to protect from harm.", xp: 20 },
  { id: "ST3-SHS3-109", mission_title: "The Endocrine System", category: "Human Body & Health", question: "What is the ENDOCRINE SYSTEM?", options: ["The system of nerves carrying electrical signals", "The system of glands that produce and release hormones directly into the bloodstream", "The digestive system", "The immune system's signalling network"], answer: "The system of glands that produce and release hormones directly into the bloodstream", explanation: "The endocrine system controls long-term processes through chemical messengers (hormones).", xp: 20 },
  { id: "ST3-SHS3-110", mission_title: "The Insulin and Diabetes", category: "Human Body & Health", question: "Insulin is produced by the pancreas. What is its function?", options: ["To break down fats", "To lower blood glucose levels by stimulating cells to absorb glucose and storing it as glycogen", "To increase heart rate", "To control growth"], answer: "To lower blood glucose levels by stimulating cells to absorb glucose and storing it as glycogen", explanation: "Insulin lowers blood glucose after eating by stimulating cellular uptake and glycogen storage.", xp: 20 },
  { id: "ST3-SHS3-111", mission_title: "The HIV/AIDS", category: "Human Body & Health", question: "HIV targets which specific cells of the immune system?", options: ["Red blood cells", "Phagocytes", "CD4+ T-helper lymphocytes", "Platelets"], answer: "Red blood cells", explanation: "HIV specifically infects and destroys CD4+ T-helper cells, which coordinate the immune response.", xp: 20 },
  { id: "ST3-SHS3-112", mission_title: "The Non-Communicable Disease", category: "Human Body & Health", question: "Cancer is a non-communicable disease. What is cancer?", options: ["A bacterial infection", "Uncontrolled division of abnormal cells that can invade surrounding tissues", "A nutritional deficiency", "An autoimmune condition"], answer: "Uncontrolled division of abnormal cells that can invade surrounding tissues", explanation: "Cancer occurs when mutations cause cells to divide uncontrollably, forming tumours.", xp: 20 },
  { id: "ST3-SHS3-113", mission_title: "The Homeostasis", category: "Human Body & Health", question: "HOMEOSTASIS is the maintenance of a stable internal environment. Which is an example?", options: ["Growing taller during puberty", "Regulating blood glucose levels between 70-100 mg/dL despite varying food intake", "Learning new skills", "Adapting to a new climate"], answer: "Regulating blood glucose levels between 70-100 mg/dL despite varying food intake", explanation: "Homeostasis maintains conditions within narrow limits despite external changes.", xp: 20 },
  { id: "ST3-SHS3-117", mission_title: "The Kidney Function", category: "Human Body & Health", question: "The kidneys filter blood to produce urine. Which is REABSORBED back into the blood?", options: ["Urea", "Excess salts", "All glucose, most water, and useful minerals (selective reabsorption)", "Harmful drugs only"], answer: "Urea", explanation: "Kidneys selectively reabsorb useful substances back into the blood.", xp: 20 },
  { id: "ST3-SHS3-119", mission_title: "The Environmental Health", category: "Human Body & Health", question: "Water pollution in Ghana's rivers due to illegal mining (galamsey) poses what health risk?", options: ["Only aesthetic problems", "Heavy metal contamination causing neurological damage, kidney failure, and cancer", "Water becomes too cold", "Dehydration from salt water"], answer: "Heavy metal contamination causing neurological damage, kidney failure, and cancer", explanation: "Galamsey releases toxic heavy metals (mercury, arsenic) into water bodies.", xp: 20 },
  { id: "ST3-SHS3-120", mission_title: "The Antibiotic Resistance", category: "Human Body & Health", question: "Why is ANTIBIOTIC RESISTANCE a growing global health threat?", options: ["Antibiotics are too expensive", "Some bacteria have evolved resistance through natural selection - making common infections untreatable", "Antibiotics cause more side effects", "Bacteria are too small"], answer: "Some bacteria have evolved resistance through natural selection - making common infections untreatable", explanation: "Overuse of antibiotics selects for resistant bacteria through natural selection.", xp: 20 },
  { id: "ST3-SHS3-123", mission_title: "The Energy Transformation", category: "Energy & Environment", question: "In a coal-fired power station, what is the sequence of energy transformations?", options: ["Electrical -> kinetic -> heat -> chemical", "Chemical (coal) -> heat -> kinetic (steam/turbine) -> electrical (generator)", "Nuclear -> electrical -> heat", "Solar -> electrical -> heat"], answer: "Chemical (coal) -> heat -> kinetic (steam/turbine) -> electrical (generator)", explanation: "Coal combustion releases chemical energy as heat, converting water to steam to drive turbines.", xp: 20 },
  { id: "ST3-SHS3-124", mission_title: "The Renewable Energy Systems", category: "Energy & Environment", question: "Which of the following is a RENEWABLE energy source?", options: ["Coal", "Natural gas", "Crude oil", "Wind energy"], answer: "Coal", explanation: "Renewable energy sources are naturally replenished: solar, wind, hydro, geothermal, biomass.", xp: 20 },
  { id: "ST3-SHS3-125", mission_title: "The Biogas", category: "Energy & Environment", question: "Biogas can be produced in Ghana from which materials?", options: ["Crude oil", "Organic waste like animal dung, kitchen waste, and agricultural residues", "Nuclear materials", "Plastic waste"], answer: "Organic waste like animal dung, kitchen waste, and agricultural residues", explanation: "Biogas is produced by anaerobic breakdown of organic matter by bacteria, producing methane.", xp: 20 },
  { id: "ST3-SHS3-127", mission_title: "The Greenhouse Effect", category: "Energy & Environment", question: "What is the NATURAL greenhouse effect?", options: ["Growing crops in greenhouses", "Greenhouse gases trapping heat from the Sun, keeping Earth warm enough for life", "Melting polar ice caps", "Ozone depletion by CFCs"], answer: "Greenhouse gases trapping heat from the Sun, keeping Earth warm enough for life", explanation: "The natural greenhouse effect is essential - without it, Earth's average temperature would be -18oC.", xp: 20 },
  { id: "ST3-SHS3-128", mission_title: "The Ozone Layer", category: "Energy & Environment", question: "What is the importance of the OZONE LAYER?", options: ["Provides oxygen for breathing", "Blocks harmful UV radiation from the Sun", "Prevents meteorites", "Reflects radio waves"], answer: "Blocks harmful UV radiation from the Sun", explanation: "The ozone layer absorbs 97-99% of the Sun's harmful UV radiation.", xp: 20 },
  { id: "ST3-SHS3-129", mission_title: "The Deforestation Impact", category: "Energy & Environment", question: "How does large-scale deforestation in Ghana contribute to climate change?", options: ["It cools the climate", "It releases stored carbon as CO2 and removes trees that would absorb CO2", "No impact", "It increases rainfall"], answer: "It releases stored carbon as CO2 and removes trees that would absorb CO2", explanation: "Forests are carbon sinks. Deforestation releases stored carbon and reduces CO2 absorption capacity.", xp: 20 },
  { id: "ST3-SHS3-136", mission_title: "The Solar Energy in Ghana", category: "Energy & Environment", question: "Ghana lies within the tropics. What is the average daily solar radiation Ghana receives?", options: ["0.5 kWh/m2/day", "2-3 kWh/m2/day", "4-6 kWh/m2/day", "10 kWh/m2/day"], answer: "0.5 kWh/m2/day", explanation: "Ghana receives 4-6 kWh/m2/day of solar radiation - one of the highest in the world.", xp: 20 },
  { id: "ST3-SHS3-137", mission_title: "The Hydroelectric Power", category: "Energy & Environment", question: "Ghana's largest hydroelectric dam is Akosombo. How is hydroelectric power generated?", options: ["Burning coal to heat water", "Water falls through turbines, converting kinetic energy to electrical via generators", "Solar panels on dam surface", "Chemical reactions in water"], answer: "Water falls through turbines, converting kinetic energy to electrical via generators", explanation: "Hydroelectric power converts the potential energy of stored water into electricity.", xp: 20 },
  { id: "ST3-SHS3-140", mission_title: "The Sustainable Development", category: "Energy & Environment", question: "What is SUSTAINABLE DEVELOPMENT?", options: ["Development maximising current economic growth", "Development meeting present needs without compromising future generations' ability to meet their own needs", "Development considering only economics", "Development stopping all industrial activity"], answer: "Development meeting present needs without compromising future generations' ability to meet their own needs", explanation: "Sustainable development balances economic development, social equity, and environmental protection.", xp: 20 },
  { id: "ST3-SHS3-142", mission_title: "The Periodic Trends", category: "Chemical Bonding & Reactions", question: "As you move down Group 1 (alkali metals) in the Periodic Table, what happens to reactivity?", options: ["Reactivity decreases because atomic radius decreases", "Reactivity increases because outer electron is further from nucleus and more easily lost", "Reactivity stays the same throughout the group", "Reactivity fluctuates unpredictably"], answer: "Reactivity increases because outer electron is further from nucleus and more easily lost", explanation: "Going down Group 1, atomic radius increases, so the outer electron is further from the nucleus and experiences less electrostatic attraction, making it easier to lose — increasing reactivity.", xp: 25 },
  { id: "ST3-SHS3-143", mission_title: "The Catalysts", category: "Chemical Bonding & Reactions", question: "A catalyst increases the rate of a chemical reaction. How does it do this?", options: ["By increasing the temperature of the reaction", "By providing an alternative reaction pathway with lower activation energy", "By increasing the pressure in the reaction vessel", "By adding more reactants"], answer: "By providing an alternative reaction pathway with lower activation energy", explanation: "A catalyst provides an alternative pathway with a lower activation energy, meaning more colliding particles have enough energy to react. Catalysts are not consumed in the reaction.", xp: 25 },
  { id: "ST3-SHS3-144", mission_title: "The Electrolysis", category: "Chemical Bonding & Reactions", question: "During electrolysis of water, which gases are produced at each electrode?", options: ["Hydrogen at anode, oxygen at cathode", "Oxygen at anode, hydrogen at cathode", "Both electrodes produce hydrogen", "Oxygen at both electrodes"], answer: "Oxygen at anode, hydrogen at cathode", explanation: "In water electrolysis: at the anode (+), water is oxidised to O₂ gas; at the cathode (-), water is reduced to H₂ gas. The volume of H₂ produced is twice the volume of O₂ (2:1 ratio).", xp: 25 },
  { id: "ST3-SHS3-145", mission_title: "The Haber Process", category: "Industrial Chemistry & Biotechnology", question: "The Haber Process manufactures which industrial chemical from N2 and H2?", options: ["Sulphuric acid", "Ammonia (NH3)", "Chlorine", "Sodium hydroxide"], answer: "Ammonia (NH3)", explanation: "The Haber Process produces ammonia, the starting material for nitrogen fertilisers.", xp: 20 },
  { id: "ST3-SHS3-150", mission_title: "The Fermentation in Industry", category: "Industrial Chemistry & Biotechnology", question: "Industrial fermentation is used to produce which of the following?", options: ["Petrol and diesel only", "Antibiotics, industrial alcohol, and citric acid using microorganisms", "Plastics and synthetic fibres only", "Nuclear fuel"], answer: "Antibiotics, industrial alcohol, and citric acid using microorganisms", explanation: "Industrial fermentation uses microorganisms to produce antibiotics, bioethanol, citric acid, and more.", xp: 20 },
  { id: "ST3-SHS3-151", mission_title: "The Biotechnology Definition", category: "Industrial Chemistry & Biotechnology", question: "What is BIOTECHNOLOGY?", options: ["The study of robots", "The use of living organisms in technology to develop products and processes", "The study of chemical reactions only", "Electronic device manufacture"], answer: "The use of living organisms in technology to develop products and processes", explanation: "Biotechnology uses biological systems to develop useful products in medicine, agriculture, and industry.", xp: 20 },
  { id: "ST3-SHS3-154", mission_title: "The PCR Technique", category: "Industrial Chemistry & Biotechnology", question: "PCR is used in COVID-19 testing and forensics. What does PCR do?", options: ["Sequences the entire genome", "Amplifies (makes millions of copies of) a specific DNA sequence for analysis", "Destroys viral DNA", "Measures blood glucose"], answer: "Amplifies (makes millions of copies of) a specific DNA sequence for analysis", explanation: "PCR rapidly amplifies tiny amounts of DNA into millions of copies for analysis.", xp: 20 },
  { id: "ST3-SHS3-159", mission_title: "The Water Treatment", category: "Industrial Chemistry & Biotechnology", question: "In water treatment plants in Ghana, which process uses chlorine?", options: ["Sedimentation", "Filtration", "Chlorination - killing bacteria and pathogens to make water safe", "Flocculation"], answer: "Sedimentation", explanation: "Water treatment: screening, sedimentation, coagulation, filtration, then chlorination for disinfection.", xp: 20 },
  { id: "ST3-SHS3-160", mission_title: "The Polymer Chemistry", category: "Industrial Chemistry & Biotechnology", question: "Plastics are polymers. What is a POLYMER?", options: ["A single large molecule", "A small molecule that bonds to others", "A long chain molecule made by joining many small repeating units (monomers)", "A type of metal alloy"], answer: "A single large molecule", explanation: "Polymers are large molecules formed by polymerisation. Natural polymers include DNA and proteins.", xp: 20 },
  { id: "ST3-SHS3-163", mission_title: "The Corrosion Prevention", category: "Industrial Chemistry & Biotechnology", question: "Galvanising protects steel by coating it with zinc. Why does this work even if the coating is scratched?", options: ["Zinc fills scratches automatically", "Zinc is more reactive than iron - it corrodes preferentially (sacrificial protection)", "Scratches make steel stronger", "Zinc reflects light"], answer: "Zinc is more reactive than iron - it corrodes preferentially (sacrificial protection)", explanation: "Zinc acts as a sacrificial anode because it is more reactive than iron.", xp: 20 },
  { id: "ST3-SHS3-165", mission_title: "The Downstream Petroleum", category: "Industrial Chemistry & Biotechnology", question: "Crude oil is refined at the Tema Oil Refinery. What process separates crude oil into fractions?", options: ["Electrolysis", "Fractional distillation based on different boiling points", "Fermentation", "Combustion"], answer: "Fractional distillation based on different boiling points", explanation: "Fractional distillation separates crude oil into fractions with different boiling point ranges.", xp: 20 },
  { id: "ST3-SHS3-167", mission_title: "The Science Applications", category: "Science, Technology & Society", question: "STEM education is prioritised in Ghana's curriculum. Why?", options: ["STEM is easier to teach", "STEM skills are essential for innovation, solving problems, and building Ghana's economy", "STEM is only for university", "Ghana has no arts teachers"], answer: "STEM skills are essential for innovation, solving problems, and building Ghana's economy", explanation: "STEM education builds critical thinking and problem-solving capacity for innovation-led growth.", xp: 20 },
  { id: "ST3-SHS3-169", mission_title: "The Technology Impact", category: "Science, Technology & Society", question: "Mobile money (MTN MoMo, Vodafone Cash) has transformed financial access in Ghana. This is an example of:", options: ["Technology replacing jobs", "Technology solving social problems by increasing financial access for unbanked populations", "Technology benefiting only urban areas", "A negative consequence of digital technology"], answer: "Technology solving social problems by increasing financial access for unbanked populations", explanation: "Mobile money has given millions of Ghanaians without bank accounts access to financial services.", xp: 20 },
  { id: "ST3-SHS3-172", mission_title: "The Space Technology", category: "Science, Technology & Society", question: "Ghana launched GhanaSat-1 in 2017. What is a practical application of satellite technology for Ghana?", options: ["Sending astronauts to the Moon", "Earth observation for monitoring deforestation, agriculture, floods, and land use mapping", "Generating electricity for Accra", "Replacing mobile networks"], answer: "Earth observation for monitoring deforestation, agriculture, floods, and land use mapping", explanation: "Earth observation satellites provide data for agriculture, forest monitoring, and disaster management.", xp: 20 },
  { id: "ST3-SHS3-174", mission_title: "The Peer Review in Science", category: "Science, Technology & Society", question: "Before a scientific paper is published, it undergoes peer review. What does this ensure?", options: ["Correct grammar", "Independent experts evaluate methodology, data, and conclusions for validity and accuracy", "Popularity on social media", "The scientist is famous"], answer: "Independent experts evaluate methodology, data, and conclusions for validity and accuracy", explanation: "Peer review is science's quality control process, checking methodology and conclusions.", xp: 20 },
  { id: "ST3-SHS3-176", mission_title: "The SDGs and Science", category: "Science, Technology & Society", question: "How does science contribute to achieving SDG 3 (Good Health) and SDG 7 (Clean Energy) in Ghana?", options: ["Science is irrelevant", "Developing vaccines, medicines (SDG3) and solar/wind/biofuels (SDG7)", "Only economics can achieve them", "SDGs can be met without research"], answer: "Developing vaccines, medicines (SDG3) and solar/wind/biofuels (SDG7)", explanation: "Science and technology are central to achieving SDGs through vaccines, solar panels, and biogas.", xp: 20 },
  { id: "ST3-SHS3-180", mission_title: "The Traditional Knowledge", category: "Science, Technology & Society", question: "Traditional Ghanaian practices like using neem leaves for malaria have scientific basis. How should this be approached?", options: ["Ignored entirely", "Investigated scientifically - active compounds tested in clinical trials", "Completely incompatible with science", "Only shared with traditional healers"], answer: "Investigated scientifically - active compounds tested in clinical trials", explanation: "Traditional knowledge can be scientifically investigated to develop standardised medicines.", xp: 20 },
  { id: "ST3-SHS3-183", mission_title: "The SHS Science Review", category: "Science, Technology & Society", question: "Which statement BEST describes the nature and purpose of science?", options: ["Science is a fixed set of facts", "Science is a systematic, evidence-based process of asking questions and testing ideas, always open to revision", "Science is only done in labs", "Science is only for doctors and engineers"], answer: "Science is a systematic, evidence-based process of asking questions and testing ideas, always open to revision", explanation: "Science is a dynamic, self-correcting process driven by evidence, not authority.", xp: 20 },
  { id: "ST3-SHS3-193", mission_title: "The Period of a Wave", category: "Waves, Light & Sound", question: "What is the PERIOD of a wave?", options: ["The distance between two crests", "The time taken for one complete wave cycle to pass a point (T = 1/f)", "The number of waves per second", "The speed of the wave"], answer: "The time taken for one complete wave cycle to pass a point (T = 1/f)", explanation: "Period (T) is the time for one complete oscillation. T = 1/f.", xp: 20 },
  { id: "ST3-SHS3-196", mission_title: "The Skin Barrier", category: "Human Body & Health", question: "The skin is the body's first line of defence. How does it provide protection?", options: ["Skin produces antibodies", "Skin is a physical and chemical barrier - unbroken skin prevents entry of pathogens, and sweat/sebum inhibit bacterial growth", "Skin produces white blood cells", "Skin attacks pathogens with enzymes"], answer: "Skin produces antibodies", explanation: "Skin provides innate immunity as the first line of defence: physical barrier plus antimicrobial secretions.", xp: 20 },
  { id: "ST3-SHS3-BONUS1", mission_title: "The Redox Reactions", category: "Chemical Bonding & Reactions", question: "In a redox (reduction-oxidation) reaction, what happens to the substance that is OXIDISED?", options: ["It gains electrons", "It loses electrons", "It gains protons", "It forms a precipitate"], answer: "It loses electrons", explanation: "Oxidation is the loss of electrons. Reduction is the gain of electrons (OIL RIG: Oxidation Is Loss, Reduction Is Gain). In the reaction Zn + CuSO4 -> ZnSO4 + Cu, Zn is oxidised (loses electrons).", xp: 25 },
  { id: "ST3-SHS3-BONUS2", mission_title: "The Carbon Footprint", category: "Energy & Environment", question: "What is a \"carbon footprint\"?", options: ["The physical size of carbon emissions", "The total amount of greenhouse gases (especially CO2) emitted directly or indirectly by an individual, organisation, or product", "The distance carbon travels in the atmosphere", "The amount of carbon in fossil fuels"], answer: "The total amount of greenhouse gases (especially CO2) emitted directly or indirectly by an individual, organisation, or product", explanation: "A carbon footprint measures total greenhouse gas emissions. For example, a person's carbon footprint includes transport, food, electricity, and goods consumption. Ghana's per capita carbon footprint is low (~0.6 tons CO2 vs global average ~4.8 tons).", xp: 20 },
  { id: "ST3-SHS3-BONUS3", mission_title: "The Digestive System", category: "Human Body & Health", question: "Where does MOST digestion and absorption of nutrients occur in the human digestive system?", options: ["The stomach", "The small intestine", "The large intestine", "The mouth"], answer: "The small intestine", explanation: "The small intestine is the primary site for digestion and absorption. Its inner surface has millions of villi and microvilli that greatly increase surface area for efficient nutrient absorption into the bloodstream. The stomach mainly digests proteins.", xp: 20 },
  { id: "ST3-SHS3-BONUS4", mission_title: "The Interference", category: "Waves, Light & Sound", question: "When two waves meet and combine, their amplitudes add together. This is called:", options: ["Diffraction", "Interference - the superposition of waves resulting in constructive (larger) or destructive (smaller/cancelled) waves", "Refraction", "Polarisation"], answer: "Interference - the superposition of waves resulting in constructive (larger) or destructive (smaller/cancelled) waves", explanation: "Interference is the superposition of two or more waves. Constructive interference occurs when crests align (amplitude increases). Destructive interference occurs when a crest meets a trough (amplitude decreases/cancels). This creates the colourful patterns in soap bubbles.", xp: 25 },
  { id: "ST3-SHS3-CE01", mission_title: "The XOR Gate", category: "Consumer Electronics & Digital Systems", question: "An XOR gate outputs 1 only when inputs DIFFER. For A=1 and B=1, output?", options: ["0", "1", "Depends", "2"], answer: "0", explanation: "XOR outputs 1 only when inputs differ. Same inputs give 0.", xp: 20 },
  { id: "ST3-SHS3-CE02", mission_title: "The Binary Addition", category: "Consumer Electronics & Digital Systems", question: "What is the binary sum of 0101 + 0011?", options: ["0110", "1000", "1001", "0111"], answer: "1000", explanation: "0101 (5) + 0011 (3) = 8 = 1000 in binary.", xp: 20 },
  { id: "ST3-SHS3-CE03", mission_title: "The Memory Types", category: "Consumer Electronics & Digital Systems", question: "What is the difference between RAM and ROM?", options: ["RAM stores data permanently; ROM loses data when powered off", "RAM is read-write and loses data when powered off; ROM is read-only and retains data without power", "RAM is slower than ROM", "ROM stores video files"], answer: "RAM is read-write and loses data when powered off; ROM is read-only and retains data without power", explanation: "RAM is volatile (temporary); ROM is non-volatile (permanent).", xp: 20 },
  { id: "ST3-SHS3-CE05", mission_title: "The 5G Network", category: "Consumer Electronics & Digital Systems", question: "5G is the fifth generation of mobile network. What key advantage does 5G offer over 4G?", options: ["Lower cost per call", "Slower but more reliable", "Significantly faster speeds, lower latency, and ability to connect more devices", "Better voice call quality only"], answer: "Lower cost per call", explanation: "5G offers speeds up to 20 Gbps, ultra-low latency, and supports millions of devices per km2.", xp: 20 },
  { id: "ST3-SHS3-CE08", mission_title: "The Renewable Energy Electronics", category: "Consumer Electronics & Digital Systems", question: "A solar charge controller in a solar panel system performs which function?", options: ["Converts sunlight to electricity", "Stores electrical energy", "Regulates voltage and current from the solar panel to prevent battery overcharging", "Converts AC to DC"], answer: "Converts sunlight to electricity", explanation: "A solar charge controller prevents battery overcharging and maximises power output.", xp: 20 },
  { id: "ST3-SHS3-CE09", mission_title: "The Oscilloscope", category: "Consumer Electronics & Digital Systems", question: "An oscilloscope is used to:", options: ["Measure mass of components", "Measure temperature", "Display and measure electrical waveforms - voltage against time", "Amplify audio signals"], answer: "Measure mass of components", explanation: "An oscilloscope displays a graph of voltage versus time for electrical signals.", xp: 20 },
  { id: "ST3-SHS3-CE10", mission_title: "The ADC", category: "Consumer Electronics & Digital Systems", question: "An Analog-to-Digital Converter (ADC) in an electronic system converts:", options: ["Digital signals to analog signals for output devices", "Continuous analog signals (e.g., temperature, sound) into discrete digital values for processing", "AC current to DC current", "Digital data into human-readable text"], answer: "Continuous analog signals (e.g., temperature, sound) into discrete digital values for processing", explanation: "ADCs convert real-world analog signals (continuous voltage) into binary digital values that microprocessors can process. The resolution (e.g., 8-bit, 10-bit) determines precision. Ghana's IoT and smart agriculture systems use ADCs for sensor data.", xp: 25 },
  { id: "ST3-SHS3-CE11", mission_title: "The Sensors", category: "Consumer Electronics & Digital Systems", question: "A thermistor is a type of sensor. What property of a thermistor changes with temperature?", options: ["Its colour changes with temperature", "Its electrical resistance changes with temperature, allowing temperature measurement", "It produces a voltage proportional to temperature", "It expands and contracts with temperature"], answer: "Its electrical resistance changes with temperature, allowing temperature measurement", explanation: "A thermistor is a temperature-sensitive resistor. NTC (Negative Temperature Coefficient) thermistors decrease resistance as temperature rises. They are used in thermostats, battery monitors, and weather stations.", xp: 20 },
  { id: "ST3-SHS3-CE12", mission_title: "The Microcontroller", category: "Consumer Electronics & Digital Systems", question: "Arduino and Raspberry Pi are popular platforms for learning electronics and programming. What distinguishes a microcontroller (like Arduino) from a single-board computer (like Raspberry Pi)?", options: ["Microcontrollers run full operating systems like Windows", "Microcontrollers are designed for real-time control of devices with limited resources, while single-board computers run full OS for more complex tasks", "Raspberry Pi cannot control any physical devices", "Arduino can connect to the internet without any additional hardware"], answer: "Microcontrollers are designed for real-time control of devices with limited resources, while single-board computers run full OS for more complex tasks", explanation: "Microcontrollers (Arduino, ESP32) are simple, low-power chips that run one program repeatedly — ideal for sensors, motors, and IoT devices. Single-board computers (Raspberry Pi) run Linux, handle complex tasks, and have more memory but consume more power.", xp: 25 },
  { id: "ST3-SHS3-CE13", mission_title: "The IoT in Agriculture", category: "Consumer Electronics & Digital Systems", question: "Internet of Things (IoT) sensors in agriculture can monitor soil moisture, temperature, and humidity. What data transmission technology is commonly used for IoT in rural Ghana where internet coverage may be limited?", options: ["Bluetooth can cover entire farms", "GSM/4G networks and LoRaWAN (Long Range Wide Area Network) can transmit sensor data over kilometres with very low power", "WiFi covers all rural areas", "Satellite internet is freely available"], answer: "GSM/4G networks and LoRaWAN (Long Range Wide Area Network) can transmit sensor data over kilometres with very low power", explanation: "LoRaWAN is ideal for IoT agriculture: it can transmit small data packets over 2-15 km with minimal power (batteries last years). GSM/4G provides wider coverage where mobile networks exist. Smart agriculture pilots in Ghana use these technologies.", xp: 25 },
  { id: "ST3-SHS3-EN01", mission_title: "The Renewable Revolution", category: "Energy & Environment", question: "Ghana's Akosombo Dam generates hydroelectric power. What energy conversion takes place?", options: ["Chemical → Electrical", "Gravitational potential → Kinetic → Electrical", "Nuclear → Thermal → Electrical", "Solar → Chemical → Electrical"], answer: "Gravitational potential → Kinetic → Electrical", explanation: "Water stored behind the dam has gravitational potential energy. When released, it flows down (kinetic energy) and spins turbines connected to generators, converting mechanical energy into electrical energy.", xp: 20 },
  { id: "ST3-SHS3-EN02", mission_title: "The Solar Potential", category: "Energy & Environment", question: "Ghana receives abundant sunshine year-round. What is the primary challenge for widespread solar adoption in rural areas?", options: ["Sunlight is not strong enough in Ghana", "High upfront cost of solar panels and battery storage despite long-term savings", "Solar panels require constant direct sunlight to function", "Solar energy cannot power household appliances"], answer: "High upfront cost of solar panels and battery storage despite long-term savings", explanation: "While the solar resource is excellent (Ghana receives ~4.5-5.5 kWh/m²/day), the initial investment for panels, inverters, and batteries is high. Battery storage is essential for nighttime use, adding significant cost. Government solar subsidies aim to reduce this barrier.", xp: 25 },
  { id: "ST3-SHS3-EN03", mission_title: "The Wind Energy", category: "Energy & Environment", question: "Wind turbines convert the kinetic energy of wind into electricity. What determines the maximum theoretical power a wind turbine can generate?", options: ["The colour of the turbine blades", "The cube of the wind speed (power ∝ wind speed³)", "The height of the turbine tower only", "The number of blades on the turbine"], answer: "The cube of the wind speed (power ∝ wind speed³)", explanation: "Wind power is proportional to the cube of wind speed (P ∝ v³×A×ρ). Doubling wind speed gives 8× the power. This is why wind farms are sited in consistently windy locations.", xp: 25 },
  { id: "ST3-SHS3-EN04", mission_title: "The Greenhouse Effect", category: "Energy & Environment", question: "The greenhouse effect is necessary for life on Earth. Which gas is the MOST significant contributor to the enhanced greenhouse effect from human activities?", options: ["Oxygen (O₂)", "Carbon dioxide (CO₂) from burning fossil fuels and deforestation", "Nitrogen (N₂)", "Hydrogen (H₂)"], answer: "Carbon dioxide (CO₂) from burning fossil fuels and deforestation", explanation: "CO₂ is the most abundant long-lived greenhouse gas from human activities. While water vapour is the most abundant GHG naturally, the enhanced greenhouse effect is primarily driven by CO₂ from burning fossil fuels and deforestation.", xp: 25 },
  { id: "ST3-SHS3-EN05", mission_title: "The Carbon Cycle", category: "Energy & Environment", question: "Deforestation in Ghana contributes to climate change. What is the primary mechanism?", options: ["Trees release carbon dioxide when cut down", "Forests are carbon sinks that absorb CO₂; removing them releases stored carbon and reduces future CO₂ absorption", "Deforestation increases rainfall", "Trees produce methane when cut"], answer: "Forests are carbon sinks that absorb CO₂; removing them releases stored carbon and reduces future CO₂ absorption", explanation: "Forests absorb CO₂ through photosynthesis. When trees are cut and burned or decompose, stored carbon is released. With fewer trees, less CO₂ is removed from the atmosphere — a double impact on atmospheric CO₂ levels.", xp: 25 },
  { id: "ST3-SHS3-EN06", mission_title: "The Energy Efficiency", category: "Energy & Environment", question: "LED bulbs use ~80% less energy than incandescent bulbs for the same light output. This is an example of:", options: ["Energy generation", "Energy efficiency — using less energy to perform the same function", "Energy storage", "Energy distribution"], answer: "Energy efficiency — using less energy to perform the same function", explanation: "Energy efficiency means getting the same output (light) with less energy input. LEDs convert ~80-90% of electricity to light, while incandescents convert only ~10% (the rest is wasted as heat).", xp: 20 },
  { id: "ST3-SHS3-EN07", mission_title: "The Waste Management", category: "Energy & Environment", question: "What is the environmental benefit of composting organic waste instead of sending it to a landfill?", options: ["Composting is faster than landfill disposal", "Composting aerobically produces nutrient-rich fertiliser and avoids methane (a potent GHG) produced in landfills", "Composting requires less space than landfills", "Composting eliminates all waste"], answer: "Composting aerobically produces nutrient-rich fertiliser and avoids methane (a potent GHG) produced in landfills", explanation: "In landfills, organic waste decomposes anaerobically, producing methane (CH₄) — a greenhouse gas ~25× more potent than CO₂. Aerobic composting produces CO₂ and nutrient-rich compost that improves soil health.", xp: 25 },
  { id: "ST3-SHS3-EN08", mission_title: "The Climate Adaptation", category: "Energy & Environment", question: "Rising sea levels threaten Ghana's coastal communities. Which is an example of climate adaptation?", options: ["Burning less fossil fuels to slow climate change", "Building sea defence walls and developing salt-tolerant crops", "Planting more trees in the northern regions", "Reducing industrial emissions"], answer: "Building sea defence walls and developing salt-tolerant crops", explanation: "Mitigation = reducing causes (e.g., emissions reduction). Adaptation = adjusting to effects (e.g., sea walls, salt-tolerant crops). Coastal communities need both strategies. Ghana's coastal zone is home to ~7 million people.", xp: 25 },
  { id: "ST3-SHS3-EN09", mission_title: "The Biomass Energy", category: "Energy & Environment", question: "In many Ghanaian communities, biomass (wood, charcoal) is the primary cooking fuel. What is the main environmental concern?", options: ["Biomass is non-renewable and will run out", "Indoor air pollution from biomass smoke causes respiratory diseases and deforestation occurs when wood is harvested unsustainably", "Biomass releases no smoke when burned", "Biomass cooking is more expensive than LPG"], answer: "Indoor air pollution from biomass smoke causes respiratory diseases and deforestation occurs when wood is harvested unsustainably", explanation: "Traditional biomass cooking produces harmful indoor air pollutants (PM2.5, CO) causing respiratory illnesses. Unsustainable wood harvesting contributes to deforestation. Clean cookstoves and LPG are alternatives promoted in Ghana.", xp: 25 },
  { id: "ST3-SHS3-EN10", mission_title: "The Nigeria-Ghana Gas", category: "Energy & Environment", question: "The West African Gas Pipeline brings natural gas to Ghana for power generation. What is the main environmental advantage of using natural gas instead of coal for electricity?", options: ["Natural gas produces no greenhouse gases", "Natural gas produces about half the CO₂ of coal and fewer air pollutants like sulphur dioxide", "Natural gas is a renewable energy source", "Natural gas requires no infrastructure"], answer: "Natural gas produces about half the CO₂ of coal and fewer air pollutants like sulphur dioxide", explanation: "Natural gas (mainly methane) produces ~50% less CO₂ per unit of electricity than coal. It also produces negligible sulphur dioxide and less particulate matter. It is a 'bridge fuel' in the transition to renewables.", xp: 25 },
  { id: "ST3-SHS3-EN11", mission_title: "The Ocean Acidification", category: "Energy & Environment", question: "Increased atmospheric CO₂ dissolves in oceans, forming carbonic acid. What is a consequence of ocean acidification?", options: ["Oceans become more alkaline, harming fish", "Ocean acidification reduces carbonate ions needed by coral and shellfish to build their calcium carbonate shells/skeletons", "Ocean acidification has no effect on marine life", "Ocean acidification increases oxygen in water"], answer: "Ocean acidification reduces carbonate ions needed by coral and shellfish to build their calcium carbonate shells/skeletons", explanation: "CO₂ + H₂O → H₂CO₃ (carbonic acid) → H⁺ + HCO₃⁻. More H⁺ ions bind with carbonate (CO₃²⁻), making it unavailable for calcifying organisms like corals, oysters, and plankton — threatening the marine food web.", xp: 25 },
  { id: "ST3-SHS3-EN12", mission_title: "The E-Waste Challenge", category: "Energy & Environment", question: "Ghana's Agbogbloshie e-waste site in Accra has gained international attention. What is the main environmental health concern from informal e-waste recycling?", options: ["E-waste contains valuable metals that should be discarded", "Burning e-waste to recover metals releases toxic fumes including lead, mercury, and brominated flame retardants into air and soil", "E-waste is completely safe to handle without protection", "E-waste only affects plants, not humans"], answer: "Burning e-waste to recover metals releases toxic fumes including lead, mercury, and brominated flame retardants into air and soil", explanation: "Informal recycling involves open burning of cables and components to extract copper and aluminium. This releases dioxins, furans, lead, mercury, and other toxics. Workers and nearby communities face elevated cancer, respiratory, and neurological risks.", xp: 25 },
  { id: "ST3-SHS3-FP11", mission_title: "The Hydraulic Press", category: "Forces, Pressure & Machines", question: "A hydraulic car lift uses a small force on a small piston to lift a heavy car on a large piston. This works because:", options: ["Air pressure pushes the car up", "The small piston creates high pressure which is transmitted equally throughout the fluid, producing a large force on the large piston", "The large piston is made of lighter material", "Gravity is reduced in hydraulic systems"], answer: "The small piston creates high pressure which is transmitted equally throughout the fluid, producing a large force on the large piston", explanation: "Pascal's Principle: pressure applied to an enclosed fluid is transmitted undiminished throughout the fluid. Force = Pressure × Area. Small area × small force = same pressure = large area × large force.", xp: 25 },
  { id: "ST3-SHS3-FP12", mission_title: "The Atmospheric Pressure", category: "Forces, Pressure & Machines", question: "Why does a drinking straw work when you suck on it?", options: ["Sucking creates a vacuum that pulls liquid up", "Sucking reduces pressure inside the straw, and the higher atmospheric pressure on the liquid surface pushes the liquid up the straw", "The liquid is attracted to the mouth by surface tension", "Capillary action pulls the liquid upward"], answer: "Sucking reduces pressure inside the straw, and the higher atmospheric pressure on the liquid surface pushes the liquid up the straw", explanation: "Atmospheric pressure (~101,325 Pa) acts on the liquid surface. When you reduce pressure inside the straw (by sucking), the greater external atmospheric pressure forces liquid up into the lower-pressure region. At high altitudes, straws work less efficiently.", xp: 25 },
  { id: "ST3-SHS3-FP13", mission_title: "The Lever Classes", category: "Forces, Pressure & Machines", question: "A crowbar used to pry open a crate has the fulcrum at one end and the load at the other. The effort is applied between them. What class of lever is this?", options: ["First-class lever", "Second-class lever (load between fulcrum and effort)", "Third-class lever (effort between fulcrum and load)", "This is not a lever system"], answer: "Second-class lever (load between fulcrum and effort)", explanation: "In a third-class lever: effort is between the fulcrum and load. This gives a mechanical advantage less than 1 but increases speed and range of motion. Examples: tweezers, fishing rod, and a crowbar used this way.", xp: 25 },
  { id: "ST3-SHS3-GEN01", mission_title: "The Pedigree Analysis", category: "Genetics & Heredity", question: "A genetic pedigree shows that a trait appears in every generation and affects males and females equally. What inheritance pattern does this suggest?", options: ["Autosomal recessive", "Autosomal dominant — the trait appears in every generation and affects both sexes equally", "X-linked recessive", "Mitochondrial inheritance"], answer: "Autosomal dominant — the trait appears in every generation and affects both sexes equally", explanation: "Autosomal dominant traits appear in every generation (no skipping) because only one copy of the dominant allele is needed. Affected individuals have an affected parent. Males and females are equally affected because the gene is on a non-sex chromosome.", xp: 25 },
  { id: "ST3-SHS3-GEN02", mission_title: "The Epigenetics", category: "Genetics & Heredity", question: "Epigenetics studies changes in gene expression that do not involve changes to the DNA sequence. Which of the following is an epigenetic mechanism?", options: ["A change in the DNA base sequence", "DNA methylation — addition of methyl groups to DNA that can silence gene expression without changing the sequence", "A mutation in a single gene", "A change in chromosome number"], answer: "DNA methylation — addition of methyl groups to DNA that can silence gene expression without changing the sequence", explanation: "Epigenetic changes alter gene activity without changing the DNA sequence. DNA methylation (adding CH₃ groups) typically silences genes. Histone modification and non-coding RNAs are other mechanisms. Environmental factors like diet can cause epigenetic changes.", xp: 30 },
  { id: "ST3-SHS3-HB16", mission_title: "The Vaccination", category: "Human Body & Health", question: "How do vaccines protect against infectious diseases?", options: ["Vaccines kill all bacteria in the body", "Vaccines expose the immune system to harmless antigens, triggering production of memory cells for rapid future response", "Vaccines provide immediate full immunity to all diseases", "Vaccines replace damaged immune cells"], answer: "Vaccines expose the immune system to harmless antigens, triggering production of memory cells for rapid future response", explanation: "Vaccines contain weakened or inactive parts of pathogens. The immune system produces antibodies and memory cells. On later exposure, memory cells trigger rapid antibody production before infection can take hold. This is 'active immunity'.", xp: 20 },
  { id: "ST3-SHS3-HB17", mission_title: "The Antibiotic Resistance", category: "Human Body & Health", question: "Antibiotic resistance is a growing global health crisis. What is the main cause of antibiotic resistance in bacteria?", options: ["Patients become resistant to antibiotics over time", "Overuse and misuse of antibiotics creates selective pressure, allowing resistant bacteria to survive and multiply", "Antibiotics cause mutations that make humans resistant", "Bacteria naturally become resistant without any outside influence"], answer: "Overuse and misuse of antibiotics creates selective pressure, allowing resistant bacteria to survive and multiply", explanation: "When antibiotics are overused or not taken as prescribed (e.g., stopping early), susceptible bacteria die but resistant ones survive and reproduce. This is natural selection in action. Ghana has antimicrobial resistance surveillance programs to address this.", xp: 25 },
  { id: "ST3-SHS3-HB18", mission_title: "The Nutrition Science", category: "Human Body & Health", question: "Why is vitamin A deficiency a significant public health concern in parts of Africa, and what is a scientific approach to addressing it?", options: ["Vitamin A is not essential for health", "Vitamin A deficiency causes blindness and weakens immunity; biofortified crops like orange-fleshed sweet potatoes provide dietary vitamin A", "Vitamin A can only be obtained from supplements", "Vitamin A deficiency only affects adults"], answer: "Vitamin A deficiency causes blindness and weakens immunity; biofortified crops like orange-fleshed sweet potatoes provide dietary vitamin A", explanation: "Vitamin A is essential for vision and immune function. Deficiency is a leading cause of preventable blindness in children. Biofortification (breeding crops with higher vitamin content) is a sustainable, food-based solution.", xp: 25 },
  { id: "ST3-SHS3-HB19", mission_title: "The Nervous System", category: "Human Body & Health", question: "A reflex action (e.g., pulling hand from a hot object) is faster than a conscious reaction because:", options: ["Reflexes use faster nerve fibres", "The reflex arc bypasses the brain — the spinal cord processes the signal directly for rapid response", "Reflexes are not real nerve signals", "Hot objects trigger a special type of nerve"], answer: "The reflex arc bypasses the brain — the spinal cord processes the signal directly for rapid response", explanation: "A reflex arc: sensory neuron → spinal cord (interneuron) → motor neuron. The brain is informed after the response begins. This short pathway eliminates the time needed for conscious processing, enabling rapid protective action.", xp: 25 },
  { id: "ST3-SHS3-HB20", mission_title: "The Endocrine System", category: "Human Body & Health", question: "Which gland in the human body is often called the 'master gland' because it controls other endocrine glands?", options: ["Thyroid gland", "Adrenal gland", "Pituitary gland", "Pancreas"], answer: "Adrenal gland", explanation: "The pituitary gland at the base of the brain secretes hormones that regulate growth, reproduction, and metabolism. It controls the thyroid, adrenal glands, and gonads by releasing stimulating hormones.", xp: 20 },
  { id: "ST3-SHS3-HB21", mission_title: "The Homeostasis", category: "Human Body & Health", question: "When you exercise vigorously, your body temperature rises. Your body responds by sweating and increasing blood flow to the skin. This regulatory process is called:", options: ["Positive feedback", "Homeostasis — the maintenance of a stable internal environment through negative feedback mechanisms", "Enzyme denaturation", "Thermal runaway"], answer: "Homeostasis — the maintenance of a stable internal environment through negative feedback mechanisms", explanation: "Homeostasis keeps internal conditions within optimal ranges. Rising temperature triggers responses (sweating cools, vasodilation increases heat loss) that counteract the change. This is negative feedback: the response opposes the stimulus.", xp: 25 },
  { id: "ST3-SHS3-IB01", mission_title: "The Fermentation", category: "Industrial Chemistry & Biotechnology", question: "In Ghana, palm wine is produced through fermentation. What is the key biochemical process?", options: ["Bacteria convert proteins into ammonia", "Yeast converts sugars (glucose) into ethanol and carbon dioxide under anaerobic conditions", "Mould breaks down cellulose into glucose", "Enzymes convert starch directly into ethanol"], answer: "Yeast converts sugars (glucose) into ethanol and carbon dioxide under anaerobic conditions", explanation: "Fermentation: yeast cells (Saccharomyces) convert glucose into ethanol (alcohol) and CO₂ gas. C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. This is anaerobic respiration (no oxygen required). The CO₂ produces bubbling.", xp: 25 },
  { id: "ST3-SHS3-IB02", mission_title: "The Bioplastics", category: "Industrial Chemistry & Biotechnology", question: "Bioplastics are being developed as alternatives to petroleum-based plastics. What is a key advantage and challenge?", options: ["Bioplastics are stronger than all conventional plastics", "Bioplastics can be made from renewable resources (e.g., corn starch) but some require specific industrial composting conditions to degrade", "Bioplastics cost nothing to produce", "Bioplastics do not need any energy to manufacture"], answer: "Bioplastics can be made from renewable resources (e.g., corn starch) but some require specific industrial composting conditions to degrade", explanation: "PLA (polylactic acid) bioplastic is made from renewable corn starch. It's compostable but requires high-temperature industrial composting facilities that are not widely available in Ghana, limiting the environmental benefit.", xp: 25 },
  { id: "ST3-SHS3-IB03", mission_title: "The Soap Making", category: "Industrial Chemistry & Biotechnology", question: "Traditional Ghanaian soap (alata samina) is made by reacting oils with a strong alkali. What is this chemical reaction called?", options: ["Hydrolysis", "Saponification — the reaction of fats/oils with an alkali (NaOH/KOH) to produce soap and glycerol", "Esterification", "Polymerisation"], answer: "Saponification — the reaction of fats/oils with an alkali (NaOH/KOH) to produce soap and glycerol", explanation: "Saponification: triglycerides (fats/oils) + sodium hydroxide → soap (sodium salts of fatty acids) + glycerol. This is how traditional alata samina and modern soaps are made. Different oils produce different soap properties.", xp: 25 },
  { id: "ST3-SHS3-IB04", mission_title: "The Water Treatment", category: "Industrial Chemistry & Biotechnology", question: "In municipal water treatment, aluminium sulphate (alum) is added. What is its purpose?", options: ["To kill bacteria in the water", "To cause suspended particles to clump together (flocculation) so they settle or can be filtered", "To add minerals to the water", "To neutralise acidic water"], answer: "To cause suspended particles to clump together (flocculation) so they settle or can be filtered", explanation: "Alum (aluminium sulphate) is a coagulant. It neutralises the charge on suspended particles, causing them to clump into larger 'flocs' that settle or are removed by filtration. This removes turbidity, colour, and many microorganisms.", xp: 25 },
  { id: "ST3-SHS3-IB05", mission_title: "The Food Preservation", category: "Industrial Chemistry & Biotechnology", question: "Salting fish (a traditional preservation method in Ghana) prevents spoilage because:", options: ["Salt adds flavour that masks spoilage", "Salt creates a hypertonic environment, drawing water out of bacterial cells through osmosis, killing or inhibiting them", "Salt chemically destroys all bacteria instantly", "Salt reacts with fish to form preservatives"], answer: "Salt creates a hypertonic environment, drawing water out of bacterial cells through osmosis, killing or inhibiting them", explanation: "High salt concentration creates osmotic pressure. Water leaves bacterial cells by osmosis, causing plasmolysis (cell shrinkage). The bacteria cannot survive or reproduce. This is why salted fish can be stored for months without refrigeration.", xp: 25 },
  { id: "ST3-SHS3-IB06", mission_title: "The pH Scale", category: "Industrial Chemistry & Biotechnology", question: "Lemon juice has pH ~2.5 and soap has pH ~9. Which statement is correct?", options: ["Lemon juice is a base and soap is an acid", "Lemon juice is an acid (pH < 7) and soap is an alkali (pH > 7); lemon juice has ~6 million times more H⁺ ions than soap", "Both are neutral", "pH cannot be measured for liquids"], answer: "Lemon juice is an acid (pH < 7) and soap is an alkali (pH > 7); lemon juice has ~6 million times more H⁺ ions than soap", explanation: "The pH scale is logarithmic. Each unit = 10× difference in H⁺ concentration. pH 2.5 → pH 9 is a 6.5 unit difference = 10^6.5 ≈ 3.2 million times more H⁺ ions. pH < 7 = acid; pH > 7 = alkali/base.", xp: 25 },
  { id: "ST3-SHS3-IB07", mission_title: "The Cement Production", category: "Industrial Chemistry & Biotechnology", question: "Ghana produces cement locally. The key chemical reaction in cement production involves heating limestone (calcium carbonate). What is produced?", options: ["Calcium oxide (quicklime) and carbon dioxide — CaCO₃ → CaO + CO₂ (thermal decomposition)", "Calcium metal and oxygen", "Calcium hydroxide and carbon", "Pure lime and water"], answer: "Calcium metal and oxygen", explanation: "Heating limestone (calcium carbonate) causes thermal decomposition: CaCO₃(s) → CaO(s) + CO₂(g). The calcium oxide (quicklime) is then mixed with clay and other materials to form cement clinker. This process is energy-intensive and produces significant CO₂.", xp: 25 },
  { id: "ST3-SHS3-IB08", mission_title: "The Polymerisation", category: "Industrial Chemistry & Biotechnology", question: "Plastics are polymers — long-chain molecules made of repeating subunits. What type of polymerisation reaction links monomers together by releasing a small molecule like water?", options: ["Addition polymerisation", "Condensation polymerisation — monomers join by eliminating a small molecule (e.g., water or HCl)", "Cracking", "Electrolysis"], answer: "Condensation polymerisation — monomers join by eliminating a small molecule (e.g., water or HCl)", explanation: "In condensation polymerisation, two different monomers react, each contributing part of the new bond and releasing a small molecule (e.g., H₂O). Nylon (diamine + dicarboxylic acid) and polyester are examples of condensation polymers.", xp: 25 },
  { id: "ST3-SHS3-IB09", mission_title: "The Cracking Process", category: "Industrial Chemistry & Biotechnology", question: "In the petroleum industry, long-chain hydrocarbons are broken down into shorter, more useful molecules. What is this process called?", options: ["Fractional distillation", "Cracking — thermal or catalytic breaking of long-chain hydrocarbons into shorter alkanes and alkenes", "Polymerisation", "Combustion"], answer: "Cracking — thermal or catalytic breaking of long-chain hydrocarbons into shorter alkanes and alkenes", explanation: "Cracking breaks large hydrocarbon molecules into smaller, more valuable ones: e.g., C₁₆H₃₄ → C₈H₁₈ + C₈H₁₆. Thermal cracking uses high temperature; catalytic cracking uses a catalyst (zeolite) at lower temperature, producing high-octane petrol and alkenes for plastics.", xp: 25 },
  { id: "ST3-SHS3-STS08", mission_title: "The Digital Divide", category: "Science, Technology & Society", question: "In Ghana, the 'digital divide' refers to the gap between those who have access to technology and those who don't. Why does this matter for education?", options: ["Technology has no impact on education", "Students without internet access miss online learning resources, digital skills development, and cannot fully participate in the modern knowledge economy", "Only wealthy countries need technology", "Digital divide only affects entertainment"], answer: "Students without internet access miss online learning resources, digital skills development, and cannot fully participate in the modern knowledge economy", explanation: "The digital divide affects educational equity. Students without reliable internet or devices cannot access online courses, educational videos, digital textbooks, or develop ICT skills essential for modern careers. Ghana's free SHS policy includes ICT infrastructure development.", xp: 25 },
  { id: "ST3-SHS3-STS09", mission_title: "The AI Ethics", category: "Science, Technology & Society", question: "Artificial Intelligence systems increasingly make decisions that affect people's lives. What is a key ethical concern?", options: ["AI systems are always perfectly fair", "AI systems can inherit and amplify human biases present in their training data, leading to unfair or discriminatory outcomes", "AI has no impact on human decision-making", "AI eliminates the need for human judgment entirely"], answer: "AI systems can inherit and amplify human biases present in their training data, leading to unfair or discriminatory outcomes", explanation: "AI learns from historical data, which may contain human biases (race, gender, socioeconomic). If training data reflects past discrimination, the AI may perpetuate or amplify it. Ethical AI requires diverse teams, careful data curation, and ongoing monitoring.", xp: 25 },
  { id: "ST3-SHS3-STS10", mission_title: "The Telemedicine", category: "Science, Technology & Society", question: "Telemedicine allows doctors to consult with patients remotely using technology. How is this particularly valuable in Ghana?", options: ["Telemedicine replaces all in-person doctor visits", "Telemedicine can extend healthcare access to rural areas where doctors are scarce, reducing travel costs and wait times", "Telemedicine only works for emergency cases", "Telemedicine is illegal in Ghana"], answer: "Telemedicine can extend healthcare access to rural areas where doctors are scarce, reducing travel costs and wait times", explanation: "Ghana has a doctor-to-patient ratio of ~1:10,000, with most doctors concentrated in urban areas. Telemedicine bridges this gap by enabling remote consultations, prescription renewals, and follow-up care for rural patients.", xp: 25 },
  { id: "ST3-SHS3-STS11", mission_title: "The Space Technology", category: "Science, Technology & Society", question: "Ghana launched its first satellite, GhanaSat-1, in 2017. What practical benefits do satellites provide for Ghana?", options: ["Satellites have no practical use for developing countries", "Satellites enable weather monitoring, agricultural planning (crop health via NDVI), coastal erosion monitoring, and communication services", "GhanaSat-1 was only for scientific prestige", "Satellites only provide television signals"], answer: "Satellites enable weather monitoring, agricultural planning (crop health via NDVI), coastal erosion monitoring, and communication services", explanation: "Small CubeSats like GhanaSat-1 carry cameras and sensors for earth observation. Applications include: monitoring crop health (NDVI), tracking deforestation, coastal erosion mapping, weather forecasting, and improving telecommunications.", xp: 25 },
  { id: "ST3-SHS3-STS12", mission_title: "The Nanotechnology", category: "Science, Technology & Society", question: "Nanotechnology involves manipulating matter at the atomic scale (1-100 nanometres). What is a current medical application of nanotechnology?", options: ["Nanotechnology only exists in science fiction", "Nanoparticles can deliver drugs directly to cancer cells, reducing side effects compared to traditional chemotherapy", "Nanotechnology is too expensive for medical use", "Nanoparticles are only used in electronics"], answer: "Nanoparticles can deliver drugs directly to cancer cells, reducing side effects compared to traditional chemotherapy", explanation: "Nanoparticles can be engineered to carry chemotherapy drugs and release them specifically at tumour sites (targeted drug delivery). This reduces damage to healthy tissue and side effects. Other applications include nanosensors for disease detection.", xp: 25 },
  { id: "ST3-SHS3-STS13", mission_title: "The Fintech Impact", category: "Science, Technology & Society", question: "Mobile money services like MTN MoMo have transformed financial inclusion in Ghana. What technological infrastructure makes this possible?", options: ["Mobile money uses satellite technology exclusively", "Mobile money uses USSD codes and mobile networks to process financial transactions on basic phones without requiring bank accounts or internet", "Mobile money requires smartphones and bank accounts", "Mobile money is a traditional banking system"], answer: "Mobile money uses USSD codes and mobile networks to process financial transactions on basic phones without requiring bank accounts or internet", explanation: "USSD (Unstructured Supplementary Service Data) works on any mobile phone. Users dial short codes to send money, pay bills, or save. This has brought financial services to millions of Ghanaians without bank accounts. Ghana is a global leader in mobile money adoption.", xp: 25 },
  { id: "ST3-SHS3-STS14", mission_title: "The Renewable Energy Policy", category: "Science, Technology & Society", question: "Ghana has a target to increase the share of renewable energy in its electricity mix. What is a scientific/technological challenge in integrating large-scale renewables into the national grid?", options: ["Renewable energy is always cheaper than fossil fuels", "Solar and wind are intermittent (generate only when sun shines/wind blows), requiring energy storage and grid management to ensure stable power supply", "Renewable energy cannot be connected to a national grid", "Solar panels require rare earth metals not available in Ghana"], answer: "Solar and wind are intermittent (generate only when sun shines/wind blows), requiring energy storage and grid management to ensure stable power supply", explanation: "Unlike hydro (which can be stored in dams), solar and wind are variable. Adding large amounts to the grid requires battery storage, pumped hydro, or other balancing mechanisms. Ghana's Renewable Energy Master Plan addresses these challenges.", xp: 25 },
  { id: "ST3-SHS3-STS15", mission_title: "The Precision Agriculture", category: "Science, Technology & Society", question: "Precision agriculture uses technology to optimise farming. How does GPS-guided tractor technology improve farming efficiency?", options: ["GPS tractors drive themselves without fuel", "GPS guidance prevents overlap in spraying/seeding, reducing input waste by 10-20% and improving yield", "GPS tractors never break down", "GPS is only useful for navigation in cities"], answer: "GPS guidance prevents overlap in spraying/seeding, reducing input waste by 10-20% and improving yield", explanation: "GPS-guided tractors with auto-steer can apply fertiliser, pesticides, and seeds with sub-metre accuracy. This eliminates gaps and overlaps, reducing input costs by 10-20% and environmental impact. Ghana's agricultural sector is beginning to adopt these technologies.", xp: 25 },
  { id: "ST3-SHS3-STS16", mission_title: "The Green Chemistry", category: "Science, Technology & Society", question: "Green chemistry aims to design chemical processes that reduce or eliminate hazardous substances. Which of the following is a green chemistry principle?", options: ["Use more solvents to improve reactions", "Design chemical products that break down into harmless substances after use (biodegradability)", "Increase energy consumption to speed up reactions", "Use more toxic reagents for faster reactions"], answer: "Design chemical products that break down into harmless substances after use (biodegradability)", explanation: "Green chemistry's 12 principles include: waste prevention, atom economy, less hazardous synthesis, biodegradable products, safer solvents, energy efficiency, renewable feedstocks, and real-time monitoring. Ghana's chemical industry is adopting these principles.", xp: 25 },
  { id: "ST3-SHS3-STS17", mission_title: "The Science Communication", category: "Science, Technology & Society", question: "During a disease outbreak in Ghana, health authorities communicate scientific information. What is the MOST important factor in effective science communication to the public?", options: ["Use highly technical medical language to show authority", "Communicate clear, accurate, actionable information in local languages through trusted community channels", "Only communicate through social media", "Avoid sharing information until the outbreak is over"], answer: "Communicate clear, accurate, actionable information in local languages through trusted community channels", explanation: "Effective science communication uses plain language, respects cultural contexts, works through trusted messengers (community leaders, local health workers), and addresses misinformation promptly. Ghana's National Health Promotion Strategy emphasises these approaches.", xp: 25 },
  { id: "ST3-SHS3-WS10", mission_title: "The Doppler Effect", category: "Waves, Light & Sound", question: "An ambulance siren sounds higher-pitched as it approaches you and lower-pitched as it moves away. What is this phenomenon called?", options: ["Refraction", "The Doppler Effect — the observed frequency of a wave changes due to relative motion between source and observer", "Diffraction", "Resonance"], answer: "The Doppler Effect — the observed frequency of a wave changes due to relative motion between source and observer", explanation: "As the ambulance approaches, sound waves are compressed (shorter wavelength = higher frequency = higher pitch). As it moves away, waves are stretched (longer wavelength = lower frequency = lower pitch). Police use this effect in radar speed guns.", xp: 25 },
  { id: "ST3-SHS3-WS11", mission_title: "The Dispersion", category: "Waves, Light & Sound", question: "A rainbow forms when sunlight passes through raindrops. What optical process creates the colours?", options: ["Reflection — light bounces off the raindrop surface", "Dispersion — white light is refracted and separated into component colours because different wavelengths bend by different amounts", "Diffraction — light bends around the edge of raindrops", "Absorption — raindrops absorb all colours except one"], answer: "Dispersion — white light is refracted and separated into component colours because different wavelengths bend by different amounts", explanation: "White light is composed of all visible colours. When entering a raindrop, different wavelengths (colours) refract by different amounts — violet bends most, red least. Internal reflection and further refraction produce the circular rainbow spectrum (ROYGBIV).", xp: 25 },
  { id: "ST3-SHS3-WS12", mission_title: "The Polarisation", category: "Waves, Light & Sound", question: "Polarised sunglasses reduce glare from horizontal surfaces like water or roads. How do they work?", options: ["They block all light from entering the eyes", "They have a polarising filter that blocks horizontally polarised reflected light while allowing vertically polarised light through", "They absorb all ultraviolet light only", "They reflect light away from the eyes"], answer: "They have a polarising filter that blocks horizontally polarised reflected light while allowing vertically polarised light through", explanation: "Sunlight reflected from flat horizontal surfaces becomes horizontally polarised. Polarised lenses have a vertical transmission axis that blocks this horizontal component, reducing glare and improving visual clarity, especially for driving and water activities.", xp: 25 },
  { id: "ST3-SHS3-WS13", mission_title: "The Seismic Waves", category: "Waves, Light & Sound", question: "During an earthquake, P-waves (primary) arrive before S-waves (secondary). Why?", options: ["P-waves are faster because they travel as longitudinal waves (compression) and can pass through solids, liquids, and gases", "S-waves are faster but arrive later", "P-waves only travel through air", "S-waves travel faster through solids than P-waves"], answer: "S-waves are faster but arrive later", explanation: "P-waves (primary) are longitudinal compression waves that travel faster (~6 km/s in crust). S-waves (secondary) are transverse shear waves that are slower (~3.5 km/s) and only travel through solids. The time difference helps locate earthquake epicentres.", xp: 25 },
  { id: "ST3-SHS3-WS14", mission_title: "The Standing Waves", category: "Waves, Light & Sound", question: "When a guitar string is plucked, it vibrates to produce a fundamental frequency and overtones. The point of zero vibration on a standing wave is called:", options: ["Antinode", "Node — the point on a standing wave where amplitude is always zero", "Crest", "Amplitude"], answer: "Node — the point on a standing wave where amplitude is always zero", explanation: "In a standing wave, nodes are points of zero displacement (destructive interference). Antinodes are points of maximum displacement (constructive interference). The fundamental frequency produces nodes at the ends of the string and an antinode in the middle.", xp: 25 },
];

// ── Helper: find which option key matches the answer text ─────────────────
function findAnswerKey(raw: RawScientificQuestion): string {
  const keys = ['A', 'B', 'C', 'D'];
  for (let i = 0; i < raw.options.length; i++) {
    if (raw.options[i] === raw.answer) return keys[i];
  }
  return 'A'; // fallback (should never happen)
}

// ── Build the full typed question bank ─────────────────────────────────────
export const SCIENTIFIC_ARENA_QUESTIONS: Question[] = RAW.map((raw, idx) => {
  const correctKey = findAnswerKey(raw);
  return {
    id: idx + 1,
    domain: 'Science',
    question: raw.question,
    options: { A: raw.options[0], B: raw.options[1], C: raw.options[2], D: raw.options[3] },
    answer_hash: hash(correctKey),
    _category: raw.category,
    _mission: raw.mission_title,
    _explanation: raw.explanation,
    _xp: raw.xp,
  };
});

// ── Get a random subset of questions (shuffled) ────────────────────────────
export function getRandomScientificQuestions(count: number): Question[] {
  const shuffled = [...SCIENTIFIC_ARENA_QUESTIONS].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

// ── Get questions by category ──────────────────────────────────────────────
export function getScientificQuestionsByCategory(category: string): Question[] {
  return SCIENTIFIC_ARENA_QUESTIONS.filter((q: any) => q._category === category);
}

// ── Get question IDs already used (for dedup) ──────────────────────────────
export const SCIENTIFIC_QUESTION_IDS = new Set(SCIENTIFIC_ARENA_QUESTIONS.map((q) => q.id));
